 10	pub(super) fn definition_style<'src>(
 11	    ctx: &mut DefinitionContext<'src, '_>,
 12	    element: usize,
 13	    control: &mut dyn WorkControl,
 14	) -> Result<CssPaint<'src>> {
 15	    let target = *ctx.shared.tokens().get(element).ok_or_else(|| bad(0))?;
 16	    let mut ancestors = Vec::new();
 17	    ancestors
 18	        .try_reserve(64)
 19	        .map_err(|_| oom(target.name.offset))?;
 20	    for (i, token) in ctx.shared.tokens().iter().enumerate().take(element) {
 21	        control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
 22	        match token.kind {
 23	            TokenKind::StartElement if token.depth < target.depth => {
 24	                while ancestors
 25	                    .last()
 26	                    .is_some_and(|(depth, _): &(usize, usize)| *depth >= token.depth)
 27	                {
 28	                    ancestors.pop();
 29	                }
 30	                if ancestors.len() >= 256 {
 31	                    return Err(crate::limit(LimitKind::Depth, token.name.offset));
 32	                }
 33	                ancestors
 34	                    .try_reserve(1)
 35	                    .map_err(|_| oom(token.name.offset))?;
 36	                ancestors.push((token.depth, i));
 37	            }
 38	            TokenKind::EmptyElement | TokenKind::EndElement => {
 39	                while ancestors
 40	                    .last()
 41	                    .is_some_and(|(depth, _): &(usize, usize)| *depth >= token.depth)
 42	                {
 43	                    ancestors.pop();
 44	                }
 45	            }
 46	            _ => {}
 47	        }
 48	    }
 49	    let mut parent = None;
 50	    for (_, i) in ancestors {
 51	        parent = Some(
 52	            ctx.shared
 53	                .compute_style(ElementId(i), parent.as_ref(), control)?,
 54	        );
 55	    }
 56	    ctx.shared
 57	        .compute_style(ElementId(element), parent.as_ref(), control)
 58	}
 59	pub(super) fn add_expansions<'src>(
 60	    ctx: &mut DefinitionContext<'src, '_>,
 61	    root: usize,
 62	    end: usize,
 63	    flavor: DecodeFlavor,
 64	    base_transform: Affine,
 65	    parent: &CssPaint<'src>,
 66	    out: &mut Vec<Expansion<'src>>,
 67	    control: &mut dyn WorkControl,
 68	) -> Result<()> {
 69	    let root_depth = ctx.shared.tokens().get(root).ok_or_else(|| bad(0))?.depth;
 70	    let mut i = root + 1;
 71	    while i < end {
 72	        let t = *ctx.shared.tokens().get(i).ok_or_else(|| bad(0))?;
 73	        control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
 74	        if !matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement)
 75	            || t.depth != root_depth + 1
 76	        {
 77	            i += 1;
 78	            continue;
 79	        }
 80	        let child_end = crate::matching_end_controlled(ctx.shared.tokens(), i, control)?;
 81	        let style = ctx
 82	            .shared
 83	            .compute_style(ElementId(i), Some(parent), control)?;
 84	        if matches!(flavor, DecodeFlavor::Clip { .. }) {
 85	            check_clip_style(&style, t.name.offset)?;
 86	        }
 87	        out.try_reserve(1).map_err(|_| oom(t.name.offset))?;
 88	        out.push(Expansion {
 89	            range: TableRange {
 90	                first: i,
 91	                count: child_end - i + 1,
 92	            },
 93	            transform: base_transform,
 94	            viewport: [
 95	                ctx.builder.scene(ctx.scene)?.viewport.width as f64,
 96	                ctx.builder.scene(ctx.scene)?.viewport.height as f64,
 97	            ],
 98	            style,
 99	            flavor,
100	            post: PostOperation::None,
101	        });
102	        i = child_end
103	            .checked_add(1)
104	            .ok_or_else(|| number_at(t.name.offset))?;
105	    }
106	    Ok(())
107	}
