109	pub(super) fn validate_clip_styles<'src>(
110	    ctx: &mut DefinitionContext<'src, '_>,
111	    root: usize,
112	    end: usize,
113	    root_style: &CssPaint<'src>,
114	    control: &mut dyn WorkControl,
115	) -> Result<()> {
116	    let root_depth = ctx.shared.tokens().get(root).ok_or_else(|| bad(0))?.depth;
117	    let mut stack = Vec::new();
118	    stack.try_reserve(64).map_err(|_| oom(0))?;
119	    stack.push((root_depth, root_style.clone()));
120	    for i in root + 1..end {
121	        let token = *ctx.shared.tokens().get(i).ok_or_else(|| bad(0))?;
122	        control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
123	        if token.kind == TokenKind::EndElement {
124	            while stack.last().is_some_and(|(depth, _)| *depth >= token.depth) {
125	                stack.pop();
126	            }
127	            continue;
128	        }
129	        if !matches!(
130	            token.kind,
131	            TokenKind::StartElement | TokenKind::EmptyElement
132	        ) {
133	            continue;
134	        }
135	        while stack.last().is_some_and(|(depth, _)| *depth >= token.depth) {
136	            stack.pop();
137	        }
138	        let parent = stack.last().map(|(_, style)| style);
139	        let style = ctx.shared.compute_style(ElementId(i), parent, control)?;
140	        check_clip_style(&style, token.name.offset)?;
141	        if token.kind == TokenKind::StartElement {
142	            if stack.len() >= crate::clip::MAX_CLIP_DEPTH {
143	                return Err(crate::limit(LimitKind::Depth, token.name.offset));
144	            }
145	            stack.try_reserve(1).map_err(|_| oom(token.name.offset))?;
146	            stack.push((token.depth, style));
147	        }
148	    }
149	    Ok(())
150	}
151	pub(super) fn check_clip_style(style: &CssPaint<'_>, _offset: usize) -> Result<()> {
152	    for p in Property::ALL {
153	        if p != Property::ClipRule && style.value(p).is_some() {
154	            return Err(unsupported(style.value(p).unwrap().span.offset));
155	        }
156	    }
157	    if let Some(v) = style.value(Property::ClipRule) {
158	        if !v.bytes.eq_ignore_ascii_case(b"nonzero") && !v.bytes.eq_ignore_ascii_case(b"evenodd") {
159	            return Err(unsupported(v.span.offset));
160	        }
161	    }
162	    Ok(())
163	}
164	pub(super) fn kind_matches(src: &[u8], span: XmlSpan, kind: DefinitionKind) -> bool {
165	    let v = span_bytes(src, span).unwrap_or_default();
166	    let expected: &[u8] = match kind {
167	        DefinitionKind::Clip => b"clipPath",
168	        DefinitionKind::Mask => b"mask",
169	        DefinitionKind::Pattern => b"pattern",
170	        DefinitionKind::Marker => b"marker",
171	        DefinitionKind::Filter => b"filter",
172	    };
173	    v == expected
174	}
175	pub(super) fn unit_flag(
176	    src: &[u8],
177	    tokens: &[XmlToken],
178	    element: usize,
179	    name: &[u8],
180	    default: bool,
181	) -> Result<bool> {
182	    let Some(s) = attr(src, tokens, element, name) else {
183	        return Ok(default);
184	    };
185	    match span_bytes(src, s).unwrap_or_default() {
186	        b"objectBoundingBox" => Ok(true),
187	        b"userSpaceOnUse" => Ok(false),
188	        _ => Err(unsupported(s.offset)),
189	    }
190	}
191	pub(super) fn mask_region(
192	    src: &[u8],
193	    span: XmlSpan,
194	    object_bbox: bool,
195	    reference: f64,
196	) -> Result<f64> {
197	    if object_bbox {
198	        let b = span_bytes(src, span).ok_or_else(|| bad(span.offset))?;
199	        let pct = b.last() == Some(&b'%');
200	        let s = if pct {
201	            XmlSpan {
202	                offset: span.offset,
203	                length: span.length - 1,
204	            }
205	        } else {
206	            span
207	        };
208	        let n = parse_number(src, s, 0.)?;
209	        Ok(if pct { n / 100. } else { n })
210	    } else {
211	        let b = span_bytes(src, span).ok_or_else(|| bad(span.offset))?;
212	        if b.last() == Some(&b'%') {
213	            return Ok(parse_number(
214	                src,
215	                XmlSpan {
216	                    offset: span.offset,
217	                    length: span.length - 1,
218	                },
219	                0.,
220	            )? * reference
221	                / 100.);
222	        }
223	        parse_length(src, span, reference)
224	    }
225	}
