240	pub(super) fn unsupported_attr(
241	    src: &[u8],
242	    tokens: &[XmlToken],
243	    element: usize,
244	    allowed: &[&[u8]],
245	) -> Option<usize> {
246	    tokens
247	        .get(element + 1..)
248	        .unwrap_or(&[])
249	        .iter()
