 74	pub fn contains(view: SceneView<'_>, clip: ClipId, x: f64, y: f64) -> bool {
 75	    let (mut next, mut depth) = (Some(clip), 0usize);
 76	    while let Some(id) = next {
 77	        if depth >= MAX_CLIP_DEPTH {
 78	            return false;
 79	        }
 80	        let Some(c) = view.clip(id) else { return false };
 81	        let Some(p) = affine_map_point(c.user_inverse, Point { x, y }) else {
 82	            return false;
 83	        };
 84	        let (mut px, mut py) = (p.x, p.y);
 85	        if c.object_bounding_box {
 86	            let [x0, y0, x1, y1] = c.bounds;
 87	            if x1 <= x0 || y1 <= y0 {
 88	                return false;
 89	            }
 90	            px = (px - x0) / (x1 - x0);
 91	            py = (py - y0) / (y1 - y0);
 92	        }
 93	        if !c.geometry.shapes.iter().any(|child| {
 94	            child.filled && point_inside(&c.geometry.edges, child.edges, child.evenodd, px, py)
 95	        }) {
 96	            return false;
 97	        }
 98	        next = c.parent;
 99	        depth += 1;
100	    }
101	    true
102	}
103	fn point_inside(edges: &[Edge], range: TableRange, evenodd: bool, x: f64, y: f64) -> bool {
104	    let Some(slice) = range.slice(edges) else {
105	        return false;
106	    };
107	    let (mut winding, mut parity) = (0i32, false);
108	    for e in slice {
109	        let up = e.a.y <= y && e.b.y > y;
110	        let down = e.b.y <= y && e.a.y > y;
111	        if !up && !down {
112	            continue;
113	        }
114	        let cross = e.a.x + (y - e.a.y) * (e.b.x - e.a.x) / (e.b.y - e.a.y);
115	        if cross > x {
116	            winding += if up { 1 } else { -1 };
117	            parity = !parity;
118	        }
119	    }
120	    if evenodd { parity } else { winding != 0 }
121	}
