129	pub fn work_counts(view: SceneView<'_>, clip: ClipId) -> Result<ClipWorkCounts> {
130	    let mut out = ClipWorkCounts::default();
131	    let (mut next, mut depth) = (Some(clip), 0);
132	    while let Some(id) = next {
133	        if depth >= MAX_CLIP_DEPTH {
134	            return Err(limit());
135	        }
136	        let c = view.clip(id).ok_or_else(invalid)?;
137	        out.chain_elements = out.chain_elements.checked_add(1).ok_or_else(arithmetic)?;
138	        out.child_shapes = out
139	            .child_shapes
140	            .checked_add(c.geometry.shapes.len())
141	            .ok_or_else(arithmetic)?;
142	        out.edges = out
143	            .edges
144	            .checked_add(c.geometry.edges.len())
145	            .ok_or_else(arithmetic)?;
146	        next = c.parent;
147	        depth += 1;
148	    }
149	    Ok(out)
150	}
151	pub fn work_units(view: SceneView<'_>, clip: ClipId) -> Result<usize> {
152	    let c = work_counts(view, clip)?;
153	    c.chain_elements
154	        .checked_add(c.child_shapes)
155	        .and_then(|x| x.checked_add(c.edges))
156	        .ok_or_else(arithmetic)
157	}
158	pub fn local_bounds(edges: &[Edge], inverse: Affine) -> Option<[f64; 4]> {
159	    if edges.is_empty() {
160	        return None;
161	    }
162	    let first = affine_map_point(inverse, edges[0].a)?;
163	    let mut b = [first.x, first.y, first.x, first.y];
164	    for e in edges {
165	        for p in [e.a, e.b] {
166	            let q = affine_map_point(inverse, p)?;
167	            b[0] = b[0].min(q.x);
168	            b[1] = b[1].min(q.y);
169	            b[2] = b[2].max(q.x);
170	            b[3] = b[3].max(q.y);
171	        }
172	    }
173	    Some(b)
174	}
