176	/// Visits document-space edges. `Ok(false)` means the visitor stopped; an invalid
177	/// mapping is reported separately so callers disable culling conservatively.
178	pub fn visit_boundary_edges(
179	    view: SceneView<'_>,
180	    clip: ClipId,
181	    mut visitor: impl FnMut(Edge) -> bool,
182	) -> Result<(bool, bool)> {
183	    let (mut id, mut valid, mut depth) = (Some(clip), true, 0);
184	    while let Some(cid) = id {
185	        if depth >= MAX_CLIP_DEPTH {
186	            return Err(limit());
187	        }
188	        let c = view.clip(cid).ok_or_else(invalid)?;
189	        let Some(local_to_doc) = inverse_affine(c.user_inverse) else {
190	            return Ok((true, false));
191	        };
192	        for child in &c.geometry.shapes {
193	            if !child.filled {
194	                continue;
195	            }
196	            let Some(edges) = child.edges.slice(&c.geometry.edges) else {
197	                return Err(invalid());
198	            };
199	            for mut edge in edges.iter().copied() {
200	                for p in [&mut edge.a, &mut edge.b] {
201	                    let mut q = *p;
202	                    if c.object_bounding_box {
203	                        q.x = c.bounds[0] + q.x * (c.bounds[2] - c.bounds[0]);
204	                        q.y = c.bounds[1] + q.y * (c.bounds[3] - c.bounds[1]);
205	                    }
206	                    let Some(mapped) = affine_map_point(local_to_doc, q) else {
207	                        valid = false;
208	                        return Ok((true, valid));
209	                    };
210	                    *p = mapped;
211	                }
212	                if !visitor(edge) {
213	                    return Ok((false, valid));
214	                }
215	            }
216	        }
217	        id = c.parent;
218	        depth += 1;
219	    }
220	    Ok((true, valid))
221	}
