479	    pub fn allocated_bytes(&self) -> Option<usize> {
480	        let mut n = self
481	            .entries
482	            .capacity()
483	            .checked_mul(std::mem::size_of::<(ClipId, Clip)>())?;
484	        for (_, c) in &self.entries {
485	            n = n.checked_add(
486	                c.geometry
487	                    .edges
488	                    .capacity()
489	                    .checked_mul(std::mem::size_of::<Edge>())?,
490	            )?;
491	            n = n.checked_add(
492	                c.geometry
493	                    .shapes
494	                    .capacity()
495	                    .checked_mul(std::mem::size_of::<ClipChild>())?,
496	            )?;
497	        }
