501	/// Copies requested clip graphs into owned, deduplicated Rust storage. IDs are
502	/// keys only; no pointer/refcount ownership crosses the overlay boundary.
503	pub fn clone_clips(
504	    view: SceneView<'_>,
505	    roots: &[ClipId],
506	    control: &mut dyn WorkControl,
507	) -> Result<ClipOverlay> {
508	    let mut out = ClipOverlay::default();
509	    let maximum_roots = MAX_CLIP_CLONE_BYTES / std::mem::size_of::<(ClipId, Clip)>();
510	    if roots.len() > maximum_roots {
511	        return Err(limit());
512	    }
513	    out.entries.try_reserve(roots.len()).map_err(|_| oom())?;
514	    if out
515	        .allocated_bytes()
516	        .is_none_or(|n| n > MAX_CLIP_CLONE_BYTES)
517	    {
518	        return Err(limit());
519	    }
520	    for root in roots {
521	        let (mut next, mut depth) = (Some(*root), 0);
522	        while let Some(id) = next {
523	            control.checkpoint().map_err(stopped)?;
524	            if out.entries.iter().any(|(seen, _)| seen == &id) {
525	                break;
526	            }
527	            if depth >= MAX_CLIP_CLONE_DEPTH {
528	                return Err(limit());
529	            }
530	            let c = view.clip(id).ok_or_else(invalid)?;
531	            let copy_bytes = c
532	                .geometry
533	                .edges
534	                .len()
535	                .checked_mul(std::mem::size_of::<Edge>())
536	                .and_then(|n| {
537	                    c.geometry
538	                        .shapes
539	                        .len()
540	                        .checked_mul(std::mem::size_of::<ClipChild>())
541	                        .and_then(|m| n.checked_add(m))
542	                })
543	                .ok_or_else(arithmetic)?;
544	            let current_bytes = out.allocated_bytes().ok_or_else(arithmetic)?;
545	            if current_bytes
546	                .checked_add(copy_bytes)
547	                .is_none_or(|n| n > MAX_CLIP_CLONE_BYTES)
548	            {
549	                return Err(limit());
550	            }
551	            let work = c
552	                .geometry
553	                .edges
554	                .len()
555	                .checked_add(c.geometry.shapes.len())
556	                .and_then(|n| n.checked_add(1))
557	                .ok_or_else(arithmetic)?;
558	            control
559	                .charge(
560	                    WorkKind::TokenVisit,
561	                    u64::try_from(work).map_err(|_| arithmetic())?,
562	                )
563	                .map_err(stopped)?;
564	            let mut edges = Vec::new();
565	            edges
566	                .try_reserve_exact(c.geometry.edges.len())
567	                .map_err(|_| oom())?;
568	            edges.extend_from_slice(&c.geometry.edges);
569	            let mut shapes = Vec::new();
570	            shapes
571	                .try_reserve_exact(c.geometry.shapes.len())
572	                .map_err(|_| oom())?;
573	            shapes.extend_from_slice(&c.geometry.shapes);
574	            let clone = Clip {
575	                geometry: ClipGeometry { edges, shapes },
576	                parent: c.parent,
577	                owner_node: c.owner_node,
578	                owner_before_suffix: c.owner_before_suffix,
579	                object_bounding_box: c.object_bounding_box,
580	                bounds: c.bounds,
581	                user_inverse: c.user_inverse,
582	            };
583	            out.entries.try_reserve(1).map_err(|_| oom())?;
584	            out.entries.push((id, clone));
585	            if out
586	                .allocated_bytes()
587	                .is_none_or(|n| n > MAX_CLIP_CLONE_BYTES)
588	            {
589	                return Err(limit());
590	            }
591	            next = c.parent;
592	            depth += 1;
593	        }
594	    }
595	    Ok(out)
596	}
597	/// Updates every matching owner on one chain. Bounds change only for valid
598	/// object-box bounds; an invalid inverse leaves the previous mapping intact.
599	pub fn update_owner(
600	    overlay: &mut ClipOverlay,
601	    id: ClipId,
602	    owner: TransformId,
603	    user_inverse: Affine,
604	    attribute_inverse: Affine,
605	    bounds: [f64; 4],
606	) -> Result<()> {
607	    let mut current = Some(id);
608	    let mut depth = 0;
609	    while let Some(key) = current {
610	        if depth >= MAX_CLIP_CLONE_DEPTH {
611	            return Err(limit());
612	        }
613	        let Some((_, clip)) = overlay.entries.iter_mut().find(|(k, _)| *k == key) else {
614	            return Err(invalid());
615	        };
616	        if clip.owner_node == Some(owner) {
617	            let candidate = if clip.owner_before_suffix {
618	                attribute_inverse
619	            } else {
620	                user_inverse
621	            };
622	            if affine_valid(candidate) {
623	                clip.user_inverse = candidate;
624	                if clip.object_bounding_box
625	                    && bounds.iter().all(|x| x.is_finite())
626	                    && bounds[2] >= bounds[0]
627	                    && bounds[3] >= bounds[1]
628	                {
629	                    clip.bounds = bounds;
630	                }
631	            }
632	        }
633	        current = clip.parent;
634	        depth += 1;
635	    }
636	    Ok(())
637	}
