 44	    control: &mut dyn WorkControl,
 45	) -> Result<PatternMapping> {
 46	    let token = tokens.get(element).ok_or_else(|| crate::invalid(0))?;
 47	    let object = unit_flag(source, tokens, element, b"patternUnits", true)?;
 48	    let content_object = unit_flag(source, tokens, element, b"patternContentUnits", false)?;
 49	    let bounds_width = bounds[2] - bounds[0];
 50	    let bounds_height = bounds[3] - bounds[1];
 51	    if (object || content_object) && (bounds_width <= 0. || bounds_height <= 0.) {
 52	        return Err(unsupported(token.name.offset));
 53	    }
 54	    let refs = [viewport.view_width, viewport.view_height];
 55	    let mut values = [0.; 4];
 56	    for (i, name) in [b"x".as_slice(), b"y", b"width", b"height"]
 57	        .iter()
 58	        .enumerate()
 59	    {
 60	        if let Some(span) = attr(source, tokens, element, name) {
 61	            values[i] = if object {
 62	                bbox_number(source, span)?
 63	            } else {
 64	                parse_length(source, span, refs[i % 2])?
 65	            };
 66	        }
 67	    }
 68	    if values[2] <= 0. || values[3] <= 0. {
 69	        return Err(number(token.name.offset));
 70	    }
 71	    let tile_origin = if object {
 72	        [
 73	            bounds[0] + values[0] * bounds_width,
 74	            bounds[1] + values[1] * bounds_height,
 75	        ]
 76	    } else {
 77	        [values[0], values[1]]
 78	    };
 79	    let tile_width = if object {
 80	        values[2] * bounds_width
 81	    } else {
 82	        values[2]
 83	    };
 84	    let tile_height = if object {
 85	        values[3] * bounds_height
 86	    } else {
 87	        values[3]
 88	    };
 89	    if !tile_origin.iter().all(|n| n.is_finite())
 90	        || !tile_width.is_finite()
 91	        || !tile_height.is_finite()
 92	        || tile_width <= 0.
 93	        || tile_height <= 0.
 94	        || tile_width > 65536.
 95	        || tile_height > 65536.
 96	    {
 97	        return Err(crate::limit(LimitKind::Patterns, token.name.offset));
 98	    }
 99	    let pattern_transform = if let Some(span) = attr(source, tokens, element, b"patternTransform") {
100	        let end = span
101	            .offset
102	            .checked_add(span.length)
103	            .ok_or_else(|| crate::invalid(span.offset))?;
104	        let (matrix, operations) = vexel_svg_values::parse_transform(
105	            source,
106	            vexel_base::Span {
107	                start: span.offset,
108	                end,
109	            },
110	        )
111	        .map_err(|error| unsupported(error.offset))?;
112	        control
113	            .charge(
114	                WorkKind::Transform,
115	                u64::try_from(operations)
116	                    .map_err(|_| crate::limit(LimitKind::Arithmetic, span.offset))?,
117	            )
118	            .map_err(crate::planner_support::stopped)?;
119	        matrix
120	    } else {
121	        affine_identity()
122	    };
123	    let pattern_inverse = crate::clip::inverse_affine(pattern_transform).ok_or_else(|| {
124	        unsupported(
125	            attr(source, tokens, element, b"patternTransform")
126	                .map_or(token.name.offset, |s| s.offset),
127	        )
128	    })?;
129	    let translate = Affine {
130	        e: -tile_origin[0],
131	        f: -tile_origin[1],
132	        ..affine_identity()
133	    };
134	    let user_to_base =
135	        affine_compose(translate, pattern_inverse).ok_or_else(|| number(token.name.offset))?;
136	    Ok(PatternMapping {
137	        definition: ElementId(element),
138	        tile_origin,
139	        tile_width,
140	        tile_height,
141	        user_to_base,
142	        pattern_scale: pattern_transform
143	            .a
144	            .hypot(pattern_transform.b)
145	            .max(pattern_transform.c.hypot(pattern_transform.d)),
146	    })
147	}
148	
149	fn bbox_number(source: &[u8], span: vexel_xml::XmlSpan) -> Result<f64> {
150	    let bytes = span_bytes(source, span).ok_or_else(|| crate::invalid(span.offset))?;
151	    let percent = bytes.last() == Some(&b'%');
152	    let number_span = if percent {
153	        vexel_xml::XmlSpan {
154	            offset: span.offset,
155	            length: span
156	                .length
157	                .checked_sub(1)
158	                .ok_or_else(|| crate::invalid(span.offset))?,
159	        }
160	    } else {
161	        span
162	    };
163	    let value = parse_number(source, number_span, 0.)?;
164	    Ok(if percent { value / 100. } else { value })
165	}
166	
167	fn unsupported(offset: usize) -> Diagnostic {
168	    Diagnostic {
169	        kind: ErrorKind::Unsupported,
170	        offset,
171	    }
172	}
173	fn number(offset: usize) -> Diagnostic {
174	    Diagnostic {
175	        kind: ErrorKind::Number,
176	        offset,
177	    }
178	}
179	
180	pub(crate) fn pattern_descriptor_from_mapping(
181	    source: &[u8],
182	    tokens: &[XmlToken],
183	    mapping: PatternMapping,
184	    bounds: [f64; 4],
185	    transform: Affine,
186	    viewport: Viewport,
187	) -> Result<PatternDescriptor> {
188	    let element = mapping.definition.0;
189	    let token = tokens.get(element).ok_or_else(|| crate::invalid(0))?;
190	    let mut density_x = viewport.width as f64 / viewport.view_width;
191	    let mut density_y = viewport.height as f64 / viewport.view_height;
192	    if !viewport.aspect.none {
193	        let density = if viewport.aspect.slice {
194	            density_x.max(density_y)
195	        } else {
196	            density_x.min(density_y)
197	        };
198	        density_x = density;
199	        density_y = density;
200	    }
201	    let transform_scale = transform
202	        .a
203	        .hypot(transform.b)
204	        .max(transform.c.hypot(transform.d));
205	    let width = (mapping.tile_width * density_x * transform_scale * mapping.pattern_scale * 4.)
206	        .ceil()
207	        .max(1.);
208	    let height = (mapping.tile_height * density_y * transform_scale * mapping.pattern_scale * 4.)
209	        .ceil()
210	        .max(1.);
211	    if !width.is_finite()
212	        || !height.is_finite()
213	        || width > 4096.
214	        || height > 4096.
215	        || width * height > 1_048_576.
216	    {
217	        return Err(crate::limit(LimitKind::Patterns, token.name.offset));
218	    }
219	    let content_object = unit_flag(source, tokens, element, b"patternContentUnits", false)?;
220	    let mut content = if let Some(span) = attr(source, tokens, element, b"viewBox") {
221	        let values = crate::common::number_list(source, span, 4).map_err(|_| Diagnostic {
222	            kind: ErrorKind::Viewport,
223	            offset: span.offset,
224	        })?;
225	        if values.len() != 4 || values[2] <= 0. || values[3] <= 0. {
226	            return Err(Diagnostic {
227	                kind: ErrorKind::Viewport,
228	                offset: span.offset,
229	            });
230	        }
231	        let aspect = if let Some(a) = attr(source, tokens, element, b"preserveAspectRatio") {
232	            let end = a
233	                .offset
234	                .checked_add(a.length)
235	                .ok_or_else(|| crate::invalid(a.offset))?;
236	            vexel_svg_values::parse_preserve_aspect(
237	                source,
238	                vexel_base::Span {
239	                    start: a.offset,
240	                    end,
241	                },
242	            )
243	            .map_err(|e| unsupported(e.offset))?
244	        } else {
245	            vexel_svg_values::Aspect {
246	                align_x: 0.5,
247	                align_y: 0.5,
248	                none: false,
249	                slice: false,
250	                set: true,
251	            }
252	        };
253	        vexel_svg_values::viewbox_transform(
254	            values[0],
255	            values[1],
256	            values[2],
257	            values[3],
258	            0.,
259	            0.,
260	            mapping.tile_width,
261	            mapping.tile_height,
262	            aspect,
263	        )
264	        .map_err(|_| Diagnostic {
265	            kind: ErrorKind::Viewport,
266	            offset: span.offset,
267	        })?
268	    } else if content_object {
269	        Affine {
270	            a: bounds[2] - bounds[0],
271	            d: bounds[3] - bounds[1],
272	            e: bounds[0],
273	            f: bounds[1],
274	            ..affine_identity()
275	        }
276	    } else {
277	        affine_identity()
278	    };
279	    if attr(source, tokens, element, b"viewBox").is_none() {
280	        content = affine_compose(
281	            Affine {
282	                e: -mapping.tile_origin[0],
283	                f: -mapping.tile_origin[1],
284	                ..affine_identity()
285	            },
286	            content,
287	        )
288	        .ok_or_else(|| crate::limit(LimitKind::Arithmetic, token.name.offset))?;
289	    }
290	    Ok(PatternDescriptor {
291	        definition: mapping.definition,
292	        width: width as u32,
293	        height: height as u32,
294	        tile_width: mapping.tile_width,
295	        tile_height: mapping.tile_height,
296	        content_transform: content,
297	        error_offset: token.name.offset,
298	    })
299	}
