 33	/// Selects the authored position-specific marker, falling back to the raw
 34	/// legacy `marker` shorthand value. CSS keeps the shorthand as its own value;
 35	/// this lookup performs the SVG marker mapping at the definition boundary.
 36	pub fn reference_value<'src>(
 37	    style: &CssPaint<'src>,
 38	    position: MarkerPosition,
 39	) -> Option<CssValue<'src>> {
 40	    let specific = match position {
 41	        MarkerPosition::Start => Property::MarkerStart,
 42	        MarkerPosition::Middle => Property::MarkerMid,
 43	        MarkerPosition::End => Property::MarkerEnd,
 44	    };
 45	    style
 46	        .value(specific)
 47	        .or_else(|| style.value(Property::Marker))
 48	}
