 29	pub(crate) fn parse_number(source: &[u8], span: XmlSpan, fallback: f64) -> Result<f64> {
 30	    if span.length == 0 {
 31	        return Ok(fallback);
 32	    }
 33	    vexel_svg_values::parse_number(
 34	        source,
 35	        Span {
 36	            start: span.offset,
 37	            end: span
 38	                .offset
 39	                .checked_add(span.length)
 40	                .ok_or_else(|| crate::invalid(span.offset))?,
 41	        },
 42	    )
 43	    .map_err(|e| map_value(e, span.offset))
 44	}
 45	pub(crate) fn region_number(source: &[u8], span: XmlSpan, fallback: f64) -> Result<f64> {
 46	    if span.length == 0 {
 47	        return Ok(fallback);
 48	    }
 49	    let b = source
 50	        .get(
 51	            span.offset
 52	                ..span
 53	                    .offset
 54	                    .checked_add(span.length)
 55	                    .ok_or_else(|| crate::invalid(span.offset))?,
 56	        )
 57	        .ok_or_else(|| crate::invalid(span.offset))?;
 58	    if b.last() == Some(&b'%') {
 59	        let n = parse_number(
 60	            source,
 61	            XmlSpan {
 62	                offset: span.offset,
 63	                length: span.length - 1,
 64	            },
 65	            fallback,
 66	        )?;
 67	        Ok(n / 100.)
 68	    } else {
 69	        parse_number(source, span, fallback)
 70	    }
 71	}
 72	pub(crate) fn number_list(source: &[u8], span: XmlSpan, max: usize) -> Result<Vec<f64>> {
 73	    let end = span
 74	        .offset
 75	        .checked_add(span.length)
 76	        .ok_or_else(|| crate::invalid(span.offset))?;
 77	    let mut cursor = vexel_svg_values::NumberCursor::new(
 78	        source,
 79	        Span {
 80	            start: span.offset,
 81	            end,
 82	        },
 83	        vexel_svg_values::ValueLimits::default(),
 84	    )
 85	    .map_err(|e| map_value(e, span.offset))?;
 86	    let mut out = Vec::new();
 87	    out.try_reserve_exact(max).map_err(|_| Diagnostic {
 88	        kind: ErrorKind::OutOfMemory,
 89	        offset: span.offset,
 90	    })?;
 91	    let first_at = cursor.absolute();
 92	    if source
 93	        .get(first_at..end)
 94	        .is_none_or(|b| b.iter().all(|c| matches!(c, b' ' | b'\t' | b'\r' | b'\n')))
 95	    {
 96	        return Ok(out);
 97	    }
 98	    loop {
 99	        if out.len() >= max {
100	            return Err(Diagnostic {
101	                kind: ErrorKind::Number,
102	                offset: cursor.absolute(),
103	            });
104	        }
105	        out.push(cursor.number().map_err(|e| map_value(e, span.offset))?);
106	        let at = cursor.absolute();
107	        let rest = source.get(at..end).ok_or_else(|| crate::invalid(at))?;
108	        if rest
109	            .iter()
110	            .all(|c| matches!(c, b' ' | b'\t' | b'\r' | b'\n'))
111	        {
112	            break;
113	        }
114	        if !cursor.separator() && !matches!(source.get(at), Some(b'+' | b'-')) {
115	            return Err(Diagnostic {
116	                kind: ErrorKind::Number,
117	                offset: at,
118	            });
119	        }
120	    }
121	    Ok(out)
122	}
