  7	/// Resolves a local `url(#id)` to the expected unprefixed definition element.
  8	/// The reference index owns duplicate-ID and visit-limit policy; this helper
  9	/// never scans or rewrites the source independently.
 10	pub fn resolve_local_definition(
 11	    shared: &mut DecodeSource<'_>,
 12	    value: XmlSpan,
 13	    expected: DefinitionKind,
 14	    control: &mut dyn WorkControl,
 15	) -> Result<ElementId> {
 16	    let source = shared.source();
 17	    let id = if expected == DefinitionKind::Clip {
 18	        parse_clip_reference(source, value)?
 19	    } else {
 20	        parse_local_url(source, value)?
 21	    };
 22	    let Some(element) = shared.find_reference(id, control)? else {
 23	        return Err(unsupported(value.offset));
 24	    };
 25	    let Some(token) = shared.tokens().get(element.0) else {
 26	        return Err(unsupported(value.offset));
 27	    };
 28	    let local = match expected {
 29	        DefinitionKind::Clip => b"clipPath".as_slice(),
 30	        DefinitionKind::Mask => b"mask",
 31	        DefinitionKind::Pattern => b"pattern",
 32	        DefinitionKind::Marker => b"marker",
 33	        DefinitionKind::Filter => b"filter",
 34	    };
 35	    if !matches!(
 36	        token.kind,
 37	        TokenKind::StartElement | TokenKind::EmptyElement
 38	    ) || token.prefix.length != 0
 39	        || span_bytes(source, token.local_name) != Some(local)
 40	    {
 41	        return Err(unsupported(value.offset));
 42	    }
 43	    Ok(element)
 44	}
