 46	fn parse_clip_reference(source: &[u8], value: XmlSpan) -> Result<XmlSpan> {
 47	    let Some(end) = value.offset.checked_add(value.length) else {
 48	        return Err(crate::invalid(value.offset));
 49	    };
 50	    let Some(bytes) = source.get(value.offset..end) else {
 51	        return Err(crate::invalid(value.offset));
 52	    };
 53	    if bytes.len() < 7 || !bytes.starts_with(b"url(#") || bytes.last() != Some(&b')') {
 54	        return Err(unsupported(value.offset));
 55	    }
 56	    Ok(XmlSpan {
 57	        offset: value
 58	            .offset
 59	            .checked_add(5)
 60	            .ok_or_else(|| crate::invalid(value.offset))?,
 61	        length: bytes.len() - 6,
 62	    })
 63	}
