 62	/// Checked byte view over an accepted immutable XML token stream.
 63	#[derive(Clone, Copy)]
 64	pub struct DefinitionSource<'a> {
 65	    pub source: &'a [u8],
 66	    pub tokens: &'a [XmlToken],
 67	}
 68	impl<'a> DefinitionSource<'a> {
 69	    pub fn new(source: &'a [u8], tokens: &'a [XmlToken]) -> Result<Self> {
 70	        for t in tokens {
 71	            for s in [t.source, t.name, t.value, t.prefix, t.local_name] {
 72	                if span_bytes(source, s).is_none() {
 73	                    return Err(invalid(s.offset));
 74	                }
 75	            }
 76	        }
 77	        Ok(Self { source, tokens })
 78	    }
 79	    pub fn attribute(&self, element: usize, name: &[u8]) -> Option<XmlSpan> {
 80	        self.tokens
 81	            .get(element.checked_add(1)?..)?
 82	            .iter()
 83	            .take_while(|t| t.kind == TokenKind::Attribute)
 84	            .find(|t| t.prefix.length == 0 && span_bytes(self.source, t.local_name) == Some(name))
 85	            .map(|t| t.value)
 86	    }
 87	    pub fn element_end(&self, element: usize) -> Result<usize> {
 88	        matching_end(self.tokens, element)
 89	    }
 90	    pub fn bytes(&self, span: XmlSpan) -> Option<&'a [u8]> {
 91	        span_bytes(self.source, span)
 92	    }
 93	    pub fn equals(&self, span: XmlSpan, value: &[u8]) -> bool {
 94	        self.bytes(span) == Some(value)
 95	    }
 96	}
 97	pub(crate) fn span_bytes(source: &[u8], span: XmlSpan) -> Option<&[u8]> {
 98	    source.get(span.offset..span.offset.checked_add(span.length)?)
 99	}
100	pub(crate) fn matching_end(tokens: &[XmlToken], element: usize) -> Result<usize> {
101	    let Some(t) = tokens.get(element) else {
102	        return Err(invalid(0));
103	    };
104	    if !matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement) {
105	        return Err(invalid(t.source.offset));
106	    }
107	    if t.kind == TokenKind::EmptyElement {
108	        return Ok(element);
109	    }
110	    tokens
111	        .iter()
112	        .enumerate()
113	        .skip(element + 1)
114	        .find_map(|(i, x)| (x.kind == TokenKind::EndElement && x.depth == t.depth).then_some(i))
115	        .ok_or_else(|| Diagnostic {
116	            kind: ErrorKind::Xml(vexel_xml::XmlError::MalformedSyntax),
117	            offset: t.name.offset,
118	        })
119	}
120	pub(crate) fn matching_end_controlled(
121	    tokens: &[XmlToken],
122	    element: usize,
123	    control: &mut dyn vexel_base::WorkControl,
124	) -> Result<usize> {
125	    let Some(t) = tokens.get(element) else {
126	        return Err(invalid(0));
127	    };
128	    if !matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement) {
129	        return Err(invalid(t.source.offset));
130	    }
131	    if t.kind == TokenKind::EmptyElement {
132	        return Ok(element);
133	    }
134	    for (i, token) in tokens.iter().enumerate().skip(element + 1) {
135	        control
136	            .charge(vexel_base::WorkKind::TokenVisit, 1)
137	            .map_err(|stop| crate::planner_support::stopped(stop))?;
138	        if token.kind == TokenKind::EndElement && token.depth == t.depth {
139	            return Ok(i);
140	        }
141	    }
142	    Err(Diagnostic {
143	        kind: ErrorKind::Xml(vexel_xml::XmlError::MalformedSyntax),
144	        offset: t.name.offset,
145	    })
146	}
