155	        .iter()
156	        .take_while(|t| t.kind == TokenKind::Attribute)
157	        .find(|t| t.prefix.length == 0 && span_bytes(source, t.local_name) == Some(name))
158	        .map(|t| t.value)
159	}
160	pub(crate) fn ascii_space(b: u8) -> bool {
161	    matches!(b, b' ' | b'\t' | b'\r' | b'\n')
162	}
