164	/// Strict local URL fragment parser. Whitespace is permitted around url content.
165	pub fn parse_local_url(source: &[u8], value: XmlSpan) -> Result<XmlSpan> {
166	    let Some(bytes) = span_bytes(source, value) else {
167	        return Err(invalid(value.offset));
168	    };
169	    let mut a = 0;
170	    let mut b = bytes.len();
171	    while a < b && ascii_space(bytes[a]) {
172	        a += 1;
173	    }
174	    while b > a && ascii_space(bytes[b - 1]) {
175	        b -= 1;
176	    }
177	    if b - a < 7 || &bytes[a..a + 4] != b"url(" || bytes[b - 1] != b')' {
178	        return Err(unsupported(value.offset));
179	    }
180	    a += 4;
181	    b -= 1;
182	    while a < b && ascii_space(bytes[a]) {
183	        a += 1;
184	    }
185	    while b > a && ascii_space(bytes[b - 1]) {
186	        b -= 1;
187	    }
188	    if b - a < 2 || bytes[a] != b'#' {
189	        return Err(unsupported(value.offset));
190	    }

