 30	static bool parse_url_id(base_bytes source, svg_xml_span value,
 31	                         svg_xml_span *id)
 32	{
 33	    if (value.offset > source.len || value.length > source.len - value.offset)
 34	        return false;
 35	    size_t first = value.offset, end = first + value.length;
 36	    while (first < end && (source.ptr[first] == ' ' ||
 37	                           source.ptr[first] == '\t' ||
 38	                           source.ptr[first] == '\r' ||
 39	                           source.ptr[first] == '\n')) first++;
 40	    while (end > first && (source.ptr[end - 1U] == ' ' ||
 41	                           source.ptr[end - 1U] == '\t' ||
 42	                           source.ptr[end - 1U] == '\r' ||
 43	                           source.ptr[end - 1U] == '\n')) end--;
 44	    if (end - first < 7U || memcmp(source.ptr + first, "url(", 4U) != 0 ||
 45	        source.ptr[end - 1U] != ')') return false;
 46	    first += 4U;
 47	    end--;
 48	    while (first < end && (source.ptr[first] == ' ' ||
 49	                           source.ptr[first] == '\t' ||
 50	                           source.ptr[first] == '\r' ||
 51	                           source.ptr[first] == '\n')) first++;
 52	    while (end > first && (source.ptr[end - 1U] == ' ' ||
 53	                           source.ptr[end - 1U] == '\t' ||
 54	                           source.ptr[end - 1U] == '\r' ||
 55	                           source.ptr[end - 1U] == '\n')) end--;
 56	    if (end - first < 2U || source.ptr[first] != '#') return false;
 57	    *id = (svg_xml_span){first + 1U, end - first - 1U};
 58	    return true;
 59	}
