 61	static size_t matching_end(const shape_traversal *traversal, size_t element)
 62	{
 63	    if (traversal->tokens[element].kind == SVG_XML_TOKEN_EMPTY_ELEMENT)
 64	        return element;
 65	    for (size_t i = element + 1U; i < traversal->token_count; ++i)
 66	        if (traversal->tokens[i].kind == SVG_XML_TOKEN_END_ELEMENT &&
 67	            traversal->tokens[i].depth == traversal->tokens[element].depth)
