 72	static bool read_mask_region(base_bytes source, svg_xml_span value,
 73	                             bool is_present, bool object_bbox,
 74	                             double percentage_reference, double fallback,
 75	                             double *out)
 76	{
 77	    if (!is_present) {
 78	        *out = fallback;
 79	        return true;
 80	    }
 81	    if (object_bbox) {
 82	        if (value.offset > source.len || value.length > source.len - value.offset)
 83	            return false;
 84	        svg_shape_number_reader reader = {
 85	            source.ptr + value.offset, value.length, 0U, value.offset};
 86	        if (!svg_shape_read_number_value(&reader, out)) return false;
 87	        svg_shape_skip_number_space(&reader);
 88	        bool percent = reader.i < reader.n && reader.p[reader.i] == '%';
 89	        if (percent) {
 90	            reader.i++;
 91	            *out /= 100.0;
 92	        }
 93	        svg_shape_skip_number_space(&reader);
 94	        return reader.i == reader.n && isfinite(*out);
 95	    }
 96	    return svg_shape_read_length(source, value, percentage_reference, out) &&
 97	           isfinite(*out);
 98	}
