100	static bool target_bounds(const svg_shape_document *document,
101	                          const svg_shape_opacity_group *group,
102	                          geom_affine transform, double bounds[4])
103	{
104	    if (group->first_shape >= group->end_shape ||
105	        group->end_shape > document->shape_count ||
106	        document->shape_edge_start == NULL || document->shape_edge_count == NULL)
107	        return false;
108	    geom_affine inverse;
109	    if (!svg_shape_affine_inverse(transform, &inverse)) return false;
110	    double min_x = INFINITY, min_y = INFINITY;
111	    double max_x = -INFINITY, max_y = -INFINITY;
112	    for (size_t shape = group->first_shape; shape < group->end_shape; ++shape) {
113	        size_t first = document->shape_edge_start[shape];
114	        size_t count = document->shape_edge_count[shape];
115	        if (first > document->edge_count || count > document->edge_count - first)
116	            return false;
117	        for (size_t edge = 0U; edge < count; ++edge) {
118	            geom_point points[2] = {document->edges[first + edge].a,
119	                                    document->edges[first + edge].b};
120	            for (size_t i = 0U; i < 2U; ++i) {
121	                geom_point local;
122	                if (!geom_affine_map_point(inverse, points[i], &local))
123	                    return false;
124	                if (local.x < min_x) min_x = local.x;
125	                if (local.x > max_x) max_x = local.x;
126	                if (local.y < min_y) min_y = local.y;
127	                if (local.y > max_y) max_y = local.y;
128	            }
129	        }
130	    }
131	    if (!isfinite(min_x) || !isfinite(min_y) || !isfinite(max_x) ||
132	        !isfinite(max_y) || max_x <= min_x || max_y <= min_y) return false;
133	    bounds[0] = min_x;
134	    bounds[1] = min_y;
135	    bounds[2] = max_x - min_x;
136	    bounds[3] = max_y - min_y;
137	    return true;
138	}
