 34	static bool parse_url_id(base_bytes source, svg_xml_span value,
 35	                         svg_xml_span *id)
 36	{
 37	    if (value.offset > source.len || value.length > source.len - value.offset)
 38	        return false;
 39	    size_t first = value.offset, end = first + value.length;
 40	    while (first < end && (source.ptr[first] == ' ' ||
 41	                           source.ptr[first] == '\t' ||
 42	                           source.ptr[first] == '\r' ||
 43	                           source.ptr[first] == '\n')) first++;
 44	    while (end > first && (source.ptr[end - 1U] == ' ' ||
 45	                           source.ptr[end - 1U] == '\t' ||
 46	                           source.ptr[end - 1U] == '\r' ||
 47	                           source.ptr[end - 1U] == '\n')) end--;
 48	    if (end - first < 7U || memcmp(source.ptr + first, "url(", 4U) != 0 ||
 49	        source.ptr[end - 1U] != ')') return false;
 50	    first += 4U;
 51	    end--;
 52	    while (first < end && (source.ptr[first] == ' ' ||
 53	                           source.ptr[first] == '\t' ||
 54	                           source.ptr[first] == '\r' ||
 55	                           source.ptr[first] == '\n')) first++;
 56	    while (end > first && (source.ptr[end - 1U] == ' ' ||
 57	                           source.ptr[end - 1U] == '\t' ||
 58	                           source.ptr[end - 1U] == '\r' ||
 59	                           source.ptr[end - 1U] == '\n')) end--;
 60	    if (end - first < 2U || source.ptr[first] != '#') return false;
 61	    *id = (svg_xml_span){first + 1U, end - first - 1U};
 62	    return true;
 63	}
