 65	static bool parse_bbox_number(base_bytes source, svg_xml_span span,
 66	                              double *out)
 67	{
 68	    if (span.offset > source.len || span.length > source.len - span.offset)
 69	        return false;
 70	    svg_shape_number_reader reader = {
 71	        source.ptr + span.offset, span.length, 0U, span.offset};
 72	    if (!svg_shape_read_number_value(&reader, out)) return false;
 73	    svg_shape_skip_number_space(&reader);
 74	    if (reader.i < reader.n && reader.p[reader.i] == '%') {
 75	        reader.i++;
 76	        *out /= 100.0;
 77	    }
 78	    svg_shape_skip_number_space(&reader);
 79	    return reader.i == reader.n && isfinite(*out);
 80	}
