160	                                       const svg_xml_token *tokens,
161	                                       size_t token_count, size_t element,
162	                                       svg_shape_diagnostic *diagnostic)
163	{
164	    static const char *const allowed[] = {
165	        "id", "class", "style", "x", "y", "width", "height",
166	        "patternUnits", "patternContentUnits", "patternTransform",
167	        "viewBox", "preserveAspectRatio"};
