190	static bool append_pattern(svg_shape_document *document,
191	                           svg_shape_pattern pattern, size_t *index,
192	                           svg_shape_diagnostic *diagnostic)
193	{
194	    if (document->pattern_count >= SVG_SHAPE_MAX_PATTERNS ||
195	        document->pattern_count == SIZE_MAX / sizeof(*document->patterns)) {
196	        fail(diagnostic, SVG_SHAPE_ERROR_LIMIT,
197	             pattern.definition_element);
198	        return false;
199	    }
200	    size_t count = document->pattern_count + 1U;
201	    if (count > SIZE_MAX / sizeof(*document->patterns)) {
202	        fail(diagnostic, SVG_SHAPE_ERROR_LIMIT,
203	             pattern.definition_element);
204	        return false;
205	    }
206	    svg_shape_pattern *grown = svg_shape_realloc(
207	        document->patterns, count * sizeof(*grown));
208	    if (grown == NULL) {
209	        fail(diagnostic, SVG_SHAPE_ERROR_OOM,
210	             pattern.definition_element);
211	        return false;
212	    }
213	    document->patterns = grown;
214	    document->patterns[document->pattern_count] = pattern;
215	    document->pattern_bytes += pattern.byte_count;
216	    *index = document->pattern_count++;
217	    return true;
218	}
