302	    nested.opacity_group_capacity = 0U;
303	    nested.text_state = NULL;
304	    nested.text_depth = 0U;
305	    nested.viewport_width = tile_width;
306	    nested.viewport_height = tile_height;
307	    nested.builder.doc = content;
308	    nested.builder.traversal = &nested;
309	    nested.builder.edge_capacity = 0U;
310	    nested.builder.shape_capacity = 0U;
311	    nested.builder.subpath_capacity = 0U;
