330	    if (!raster_shape_render(content, &tile, traversal->diagnostic)) {
331	        svg_shape_document_destroy(content);
332	        svg_shape_free(content);
333	        return false;
334	    }
335	    size_t bytes = tile.byte_count;
336	    if (bytes == 0U || bytes > SVG_SHAPE_MAX_PATTERN_BYTES ||
337	        traversal->pattern_bytes >
338	            SVG_SHAPE_MAX_PATTERN_BYTES - bytes ||
339	        owner->pattern_bytes > SVG_SHAPE_MAX_PATTERN_BYTES - bytes) {
340	        raster_tile_destroy(&tile);
341	        svg_shape_document_destroy(content);
342	        svg_shape_free(content);
