345	        return false;
346	    }
347	    uint8_t *pixels = svg_shape_malloc(bytes);
348	    if (pixels == NULL) {
349	        raster_tile_destroy(&tile);
350	        svg_shape_document_destroy(content);
351	        svg_shape_free(content);
352	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_OOM,
353	             traversal->tokens[definition].name.offset);
354	        return false;
355	    }
356	    memcpy(pixels, tile.rgba, bytes);
357	    raster_tile_destroy(&tile);
358	    svg_shape_document_destroy(content);
359	    svg_shape_free(content);
360	    svg_shape_pattern pattern = {
361	        .rgba = pixels,
362	        .byte_count = bytes,
363	        .width = width,
364	        .height = height,
365	        .definition_element = definition,
366	        .tile_width = tile_width,
367	        .tile_height = tile_height,
368	        .content_transform = content_transform};
369	    if (!append_pattern(owner, pattern, pattern_index,
370	                        traversal->diagnostic)) {
371	        svg_shape_free(pixels);
372	        return false;
373	    }
374	    traversal->pattern_bytes += bytes;
375	    return true;
376	}
