 70	                                    const svg_xml_token *tokens,
 71	                                    size_t token_count, size_t marker,
 72	                                    svg_shape_diagnostic *diagnostic)
 73	{
 74	    static const char *const supported[] = {
 75	        "id", "class", "style", "markerWidth", "markerHeight", "refX",
 76	        "refY", "markerUnits", "orient", "viewBox",
 77	        "preserveAspectRatio", "overflow"};
 78	    for (size_t i = marker + 1U;
 79	         i < token_count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
 80	        if (tokens[i].prefix.length != 0U) {
 81	            fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, tokens[i].name.offset);
 82	            return false;
 83	        }
 84	        bool found = false;
 85	        for (size_t j = 0U; j < sizeof(supported) / sizeof(supported[0]); ++j)
 86	            if (svg_shape_span_eq(source, tokens[i].local_name, supported[j])) {
 87	                found = true;
 88	                break;
 89	            }
 90	        if (!found) {
 91	            fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, tokens[i].name.offset);
 92	            return false;
 93	        }
 94	        if (svg_shape_span_eq(source, tokens[i].local_name, "overflow") &&
 95	            !svg_css_keyword_equals(source, tokens[i].value, "hidden") &&
 96	            !svg_css_keyword_equals(source, tokens[i].value, "visible")) {
 97	            fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, tokens[i].value.offset);
 98	            return false;
 99	        }
100	    }
101	    return true;
102	}
103	
104	static double direction_angle(geom_edge edge)
105	{
106	    return atan2(edge.b.y - edge.a.y, edge.b.x - edge.a.x);
107	}
108	
109	static double middle_angle(geom_edge incoming, geom_edge outgoing)
110	{
111	    double first = direction_angle(incoming);
112	    double difference = remainder(direction_angle(outgoing) - first,
113	                                  2.0 * SHAPE_MARKER_PI);
114	    return first + difference * 0.5;
115	}
116	
117	static double element_scale(geom_affine transform)
118	{
119	    double xx = transform.a * transform.a + transform.b * transform.b;
120	    double yy = transform.c * transform.c + transform.d * transform.d;
121	    double xy = transform.a * transform.c + transform.b * transform.d;
122	    double maximum = (xx + yy + hypot(xx - yy, 2.0 * xy)) * 0.5;
123	    return sqrt(fmax(0.0, maximum));
124	}
125	
126	static bool parse_orient(base_bytes source, svg_xml_span span, bool *automatic,
127	                         bool *reverse, double *degrees)
128	{
129	    *automatic = false;
130	    *reverse = false;
131	    if (svg_css_keyword_equals(source, span, "auto")) {
132	        *automatic = true;
133	        return true;
134	    }
135	    if (svg_css_keyword_equals(source, span, "auto-start-reverse")) {
136	        *automatic = true;
137	        *reverse = true;
138	        return true;
139	    }
140	    if (span.offset > source.len || span.length > source.len - span.offset)
141	        return false;
142	    svg_shape_number_reader reader = {
143	        source.ptr + span.offset, span.length, 0U, span.offset};
144	    if (!svg_shape_read_number_value(&reader, degrees)) return false;
145	    svg_shape_skip_number_space(&reader);
146	    if (reader.i < reader.n && reader.n - reader.i == 3U &&
147	        memcmp(reader.p + reader.i, "deg", 3U) == 0) reader.i += 3U;
148	    svg_shape_skip_number_space(&reader);
149	    return reader.i == reader.n && isfinite(*degrees);
150	}
151	
152	static bool compose_marker_transform(geom_point position, double angle,
153	                                     double scale, geom_affine content,
154	                                     geom_point reference,
155	                                     geom_affine *out)
156	{
157	    geom_affine translation = {
158	        1.0, 0.0, 0.0, 1.0, position.x, position.y};
159	    geom_affine rotation = {
160	        cos(angle), sin(angle), -sin(angle), cos(angle), 0.0, 0.0};
161	    geom_affine marker_scale = {scale, 0.0, 0.0, scale, 0.0, 0.0};
162	    geom_affine reference_shift = {
163	        1.0, 0.0, 0.0, 1.0, -reference.x, -reference.y};
164	    geom_affine result;
165	    if (!geom_affine_compose(translation, rotation, &result) ||
166	        !geom_affine_compose(result, marker_scale, &result) ||
167	        !geom_affine_compose(result, reference_shift, &result) ||
168	        !geom_affine_compose(result, content, out)) return false;
169	    return true;
170	}
171	
172	static bool marker_definition_parent_style(shape_traversal *traversal,
173	                                          size_t marker,
174	                                          svg_css_paint *out_parent)
175	{
176	    size_t ancestors[SHAPE_MAX_XML_DEPTH + 1U];
177	    size_t ancestor_count = 0U;
178	    for (size_t i = 0U; i < marker; ++i) {
179	        if (traversal->marker_style_token_visits >=
180	                SHAPE_MAX_TRAVERSAL_VISITS) {
181	            fail(traversal->diagnostic, SVG_SHAPE_ERROR_LIMIT,
182	                 traversal->tokens[marker].name.offset);
183	            return false;
184	        }
185	        traversal->marker_style_token_visits++;
186	        if ((i & 255U) == 0U && svg_shape_traverse_cancelled(
187	                traversal, traversal->tokens[i].source.offset)) return false;
188	        const svg_xml_token *token = &traversal->tokens[i];
189	        if (token->kind == SVG_XML_TOKEN_START_ELEMENT) {
190	            while (ancestor_count != 0U &&
191	                   traversal->tokens[ancestors[ancestor_count - 1U]].depth >=
192	                       token->depth) ancestor_count--;
193	            if (ancestor_count == sizeof(ancestors) / sizeof(ancestors[0])) {
194	                fail(traversal->diagnostic, SVG_SHAPE_ERROR_LIMIT,
195	                     token->name.offset);
196	                return false;
197	            }
198	            ancestors[ancestor_count++] = i;
199	        } else if (token->kind == SVG_XML_TOKEN_EMPTY_ELEMENT ||
200	                   token->kind == SVG_XML_TOKEN_END_ELEMENT) {
201	            while (ancestor_count != 0U &&
202	                   traversal->tokens[ancestors[ancestor_count - 1U]].depth >=
203	                       token->depth) ancestor_count--;
204	        }
205	    }
206	    svg_css_paint inherited = svg_css_initial_paint();
207	    bool has_parent = false;
208	    for (size_t i = 0U; i < ancestor_count; ++i) {
209	        svg_css_paint computed;
210	        if (!svg_shape_traverse_compute_style(
211	                traversal, ancestors[i], has_parent ? &inherited : NULL,
212	                &computed)) return false;
213	        inherited = computed;
214	        has_parent = true;
215	    }
216	    *out_parent = inherited;
217	    return true;
218	}
219	
220	static bool make_marker(shape_traversal *traversal, size_t marker,
221	                        size_t shape, marker_position_kind kind,
222	                        geom_point position, double tangent,
223	                        geom_affine source_transform,
224	                        size_t render_depth)
225	{
226	    if (traversal->active_marker_depth >=
227	            sizeof(traversal->active_markers) /
228	                sizeof(traversal->active_markers[0]) ||
229	        traversal->marker_instances >= SHAPE_MARKER_MAX_INSTANCES) {
230	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_LIMIT,
231	             traversal->tokens[marker].name.offset);
232	        return false;
233	    }
234	    for (size_t i = 0U; i < traversal->active_marker_depth; ++i) {
235	        if (traversal->active_markers[i] == marker) {
236	            fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
237	                 traversal->tokens[marker].name.offset);
238	            return false;
239	        }
240	    }
241	    if (!parse_marker_attributes(traversal->source, traversal->tokens,
242	            traversal->token_count, marker, traversal->diagnostic)) return false;
243	    size_t marker_end = svg_shape_traverse_matching_end(traversal, marker);
244	    if (marker_end == SIZE_MAX) {
245	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_XML,
246	             traversal->tokens[marker].name.offset);
247	        return false;
248	    }
249	    svg_css_paint marker_parent_style, marker_style;
250	    if (!marker_definition_parent_style(traversal, marker,
251	                                        &marker_parent_style) ||
252	        !svg_shape_traverse_compute_style(traversal, marker,
253	            &marker_parent_style, &marker_style)) return false;
254	    marker_style.values[SVG_CSS_MARKER] = (svg_css_value){0};
255	    marker_style.values[SVG_CSS_MARKER_START] = (svg_css_value){0};
256	    marker_style.values[SVG_CSS_MARKER_MID] = (svg_css_value){0};
257	    marker_style.values[SVG_CSS_MARKER_END] = (svg_css_value){0};
258	    svg_xml_span value = {0};
259	    double width = 3.0, height = 3.0;
260	    if (attr(traversal->source, traversal->tokens, traversal->token_count,
261	             marker, "markerWidth", &value) &&
262	        !svg_shape_read_length(traversal->source, value,
263	                               traversal->viewport_width, &width)) {
264	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_NUMBER, value.offset);
265	        return false;
266	    }
267	    if (attr(traversal->source, traversal->tokens, traversal->token_count,
268	             marker, "markerHeight", &value) &&
269	        !svg_shape_read_length(traversal->source, value,
270	                               traversal->viewport_height, &height)) {
271	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_NUMBER, value.offset);
272	        return false;
273	    }
274	    if (!isfinite(width) || !isfinite(height) || width <= 0.0 || height <= 0.0 ||
275	        width > 4096.0 || height > 4096.0) {
276	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_LIMIT,
277	             traversal->tokens[marker].name.offset);
278	        return false;
279	    }
280	    double ref_x = 0.0, ref_y = 0.0;
281	    if (attr(traversal->source, traversal->tokens, traversal->token_count,
282	             marker, "refX", &value) &&
283	        !svg_shape_read_length(traversal->source, value, width, &ref_x)) {
284	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_NUMBER, value.offset);
285	        return false;
286	    }
287	    if (attr(traversal->source, traversal->tokens, traversal->token_count,
288	             marker, "refY", &value) &&
289	        !svg_shape_read_length(traversal->source, value, height, &ref_y)) {
290	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_NUMBER, value.offset);
291	        return false;
292	    }
293	    bool automatic = false, reverse = false;
294	    double degrees = 0.0;
295	    if (attr(traversal->source, traversal->tokens, traversal->token_count,
296	             marker, "orient", &value) &&
297	        !parse_orient(traversal->source, value, &automatic, &reverse,
298	                      &degrees)) {
299	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, value.offset);
300	        return false;
301	    }
302	    bool stroke_units = true;
303	    if (attr(traversal->source, traversal->tokens, traversal->token_count,
304	             marker, "markerUnits", &value)) {
305	        if (svg_shape_span_eq(traversal->source, value, "userSpaceOnUse"))
306	            stroke_units = false;
307	        else if (!svg_shape_span_eq(traversal->source, value, "strokeWidth")) {
308	            fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
309	                 value.offset);
310	            return false;
311	        }
312	    }
313	    double units = 1.0;
314	    if (stroke_units) {
315	        if (shape >= traversal->builder.doc->shape_count ||
316	            traversal->builder.doc->strokes == NULL) {
317	            fail(traversal->diagnostic, SVG_SHAPE_ERROR_INVALID_ARGUMENT,
318	                 traversal->tokens[marker].name.offset);
319	            return false;
320	        }
321	        units = traversal->builder.doc->strokes[shape].width *
322	                element_scale(source_transform);
323	        if (!isfinite(units) || units <= 0.0) units = 1.0;
324	    }
325	    geom_affine content = geom_affine_identity();
326	    geom_point reference = {ref_x, ref_y};
327	    svg_xml_span view_box_span = {0};
328	    double child_width = width, child_height = height;
329	    if (attr(traversal->source, traversal->tokens, traversal->token_count,
330	             marker, "viewBox", &view_box_span)) {
331	        double box[4];
332	        svg_shape_aspect aspect = {0.5, 0.5, false, false, true};
333	        if (!svg_shape_read_number_list(traversal->source, view_box_span,
334	                                        box, 4U) ||
335	            box[2] <= 0.0 || box[3] <= 0.0) {
336	            fail(traversal->diagnostic, SVG_SHAPE_ERROR_VIEWPORT,
337	                 view_box_span.offset);
338	            return false;
339	        }
340	        if (attr(traversal->source, traversal->tokens,
341	                 traversal->token_count, marker, "preserveAspectRatio", &value) &&
342	            !svg_shape_parse_preserve_aspect(traversal->source, value, &aspect)) {
343	            fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
344	                 value.offset);
345	            return false;
346	        }
347	        if (!svg_shape_viewbox_transform(box[0], box[1], box[2], box[3],
348	                0.0, 0.0, width, height, aspect, &content) ||
349	            !geom_affine_map_point(content, reference, &reference)) {
350	            fail(traversal->diagnostic, SVG_SHAPE_ERROR_VIEWPORT,
351	                 view_box_span.offset);
352	            return false;
353	        }
354	        child_width = box[2];
355	        child_height = box[3];
356	    }
357	    double angle = automatic ? tangent : degrees * SHAPE_MARKER_PI / 180.0;
358	    if (kind == MARKER_POSITION_START && reverse) angle += SHAPE_MARKER_PI;
359	    if (!svg_shape_traverse_account_transform(traversal, 1U,
360	            traversal->tokens[marker].name.offset)) return false;
361	    geom_affine marker_transform;
362	    if (!compose_marker_transform(position, angle, units, content, reference,
363	                                  &marker_transform)) {
364	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_NUMBER,
365	             traversal->tokens[marker].name.offset);
366	        return false;
367	    }
368	    if (marker_end == marker) return true;
369	
370	    traversal->active_markers[traversal->active_marker_depth++] = marker;
371	    traversal->marker_instances++;
372	    size_t group = SVG_SHAPE_NO_GROUP;
373	    bool ok = svg_shape_traverse_begin_opacity_group(
374	        traversal, &marker_style, &group);
375	    double previous_width = traversal->viewport_width;
376	    double previous_height = traversal->viewport_height;
377	    traversal->viewport_width = child_width;
378	    traversal->viewport_height = child_height;
379	    traversal->builder.viewport_width = child_width;
380	    traversal->builder.viewport_height = child_height;
381	    if (ok) {
382	        svg_xml_span clip = {0};
383	        if (svg_css_paint_value(&marker_style, SVG_CSS_CLIP_PATH, &clip) &&
384	            !svg_css_keyword_equals(traversal->source, clip, "none")) {
385	            fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, clip.offset);
386	            ok = false;
387	        } else {
388	            ok = svg_shape_traverse_walk_range(
389	                traversal, marker + 1U, marker_end, marker_transform,
390	                &marker_style, render_depth + 1U);
391	        }
392	    }
393	    if (ok)
394	        ok = svg_shape_traverse_attach_mask(traversal, marker, group,
395	                                            &marker_style, marker_transform);
396	    svg_shape_traverse_finish_opacity_group(traversal, group);
397	    traversal->viewport_width = previous_width;
398	    traversal->viewport_height = previous_height;
399	    traversal->builder.viewport_width = previous_width;
400	    traversal->builder.viewport_height = previous_height;
401	    traversal->active_marker_depth--;
402	    return ok;
403	}
404	
405	static bool emit_marker(shape_traversal *traversal, size_t shape,
406	                        const svg_css_paint *style, svg_css_property property,
407	                        marker_position_kind kind, geom_point point,
408	                        double tangent, geom_affine source_transform,
409	                        size_t render_depth)
410	{
411	    svg_xml_span value = {0}, id;
412	    if (!svg_css_paint_value(style, property, &value) ||
413	        svg_css_keyword_equals(traversal->source, value, "none")) return true;
414	    size_t marker = 0U;
415	    if (!parse_url_id(traversal->source, value, &id) ||
416	        !svg_reference_index_find(traversal->source, traversal->tokens,
417	            traversal->token_count, &traversal->references, id, &marker)) {
418	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, value.offset);
419	        return false;
420	    }
421	    if (!svg_shape_traverse_element_name(traversal->source,
422	            &traversal->tokens[marker], "marker")) {
423	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, value.offset);
424	        return false;
425	    }
426	    return make_marker(traversal, marker, shape, kind, point, tangent,
427	                       source_transform, render_depth);
428	}
429	
430	static bool emit_mid_marker(shape_traversal *traversal, size_t shape,
431	                            const svg_css_paint *style, geom_point point,
432	                            geom_edge incoming, geom_edge outgoing,
433	                            geom_affine transform, size_t render_depth)
434	{
435	    return emit_marker(traversal, shape, style, SVG_CSS_MARKER_MID,
436	                       MARKER_POSITION_MID, point,
437	                       middle_angle(incoming, outgoing), transform,
438	                       render_depth);
439	}
440	
441	static bool flush_path_subpath(shape_traversal *traversal, size_t shape,
442	                               const svg_css_paint *style,
443	                               marker_subpath *subpath,
444	                               geom_affine transform, size_t render_depth)
445	{
446	    if (!subpath->has_edges) return true;
447	    bool ok = emit_marker(traversal, shape, style, SVG_CSS_MARKER_START,
448	        MARKER_POSITION_START, subpath->first.a,
449	        direction_angle(subpath->first), transform, render_depth) &&
450	        emit_marker(traversal, shape, style, SVG_CSS_MARKER_END,
451	        MARKER_POSITION_END, subpath->last.b,
452	        direction_angle(subpath->last), transform, render_depth);
453	    *subpath = (marker_subpath){0};
454	    return ok;
455	}
456	
457	static bool path_markers(shape_traversal *traversal, size_t shape,
458	                         const svg_css_paint *style, geom_affine transform,
459	                         size_t render_depth)
460	{
461	    const svg_shape_document *document = traversal->builder.doc;
462	    size_t lower = 0U, upper = document->path_segment_count;
463	    while (lower < upper) {
464	        size_t middle = lower + (upper - lower) / 2U;
465	        if (document->path_segments[middle].shape_index < shape)
466	            lower = middle + 1U;
467	        else upper = middle;
468	    }
469	    marker_subpath current = {0};
470	    for (size_t i = lower; i < document->path_segment_count &&
471	         document->path_segments[i].shape_index == shape; ++i) {
472	        /* Copy by value: flushing emits markers whose nested paths append to
473	         * and may reallocate path_segments. */
474	        const svg_shape_path_segment segment_copy = document->path_segments[i];
475	        const svg_shape_path_segment *segment = &segment_copy;
476	        char command = segment->command;
477	        if (command >= 'a' && command <= 'z') command = (char)(command - 'a' + 'A');
478	        if (command == 'M' && !flush_path_subpath(
479	                traversal, shape, style, &current, transform, render_depth))
480	            return false;
481	        if (segment->edge_count == 0U) continue;
482	        if (segment->first_edge > document->edge_count ||
483	            segment->edge_count > document->edge_count - segment->first_edge) {
484	            fail(traversal->diagnostic, SVG_SHAPE_ERROR_INVALID_ARGUMENT,
485	                 segment->source_offset);
486	            return false;
487	        }
488	        const geom_edge first = document->edges[segment->first_edge];
489	        const geom_edge last = document->edges[
490	            segment->first_edge + segment->edge_count - 1U];
491	        if (!current.has_edges) {
492	            current.first = first;
493	            current.last = last;
494	            current.has_edges = true;
495	            if (!emit_marker(traversal, shape, style, SVG_CSS_MARKER_START,
496	                    MARKER_POSITION_START, first.a, direction_angle(first),
497	                    transform, render_depth)) return false;
498	        } else {
499	            if (!emit_mid_marker(traversal, shape, style, current.last.b,
500	                    current.last, first, transform, render_depth)) return false;
501	            current.last = last;
502	        }
503	        if (command == 'Z' && !flush_path_subpath(
504	                traversal, shape, style, &current, transform, render_depth))
505	            return false;
506	    }
507	    return flush_path_subpath(traversal, shape, style, &current,
508	                              transform, render_depth);
509	}
510	
511	static bool primitive_markers(shape_traversal *traversal, size_t element,
512	                              size_t shape, const svg_css_paint *style,
513	                              geom_affine transform, size_t render_depth)
514	{
515	    const svg_shape_document *document = traversal->builder.doc;
516	    if (shape >= document->shape_count || document->shape_edge_start == NULL ||
517	        document->shape_edge_count == NULL) return false;
518	    size_t first = document->shape_edge_start[shape];
519	    size_t count = document->shape_edge_count[shape];
520	    bool line = svg_shape_traverse_element_name(traversal->source,
521	        &traversal->tokens[element], "line");
522	    bool polyline = svg_shape_traverse_element_name(traversal->source,
523	        &traversal->tokens[element], "polyline");
524	    bool polygon = svg_shape_traverse_element_name(traversal->source,
525	        &traversal->tokens[element], "polygon");
526	    if (!line && !polyline && !polygon) return true;
527	    size_t path_edges = count;
528	    if (polyline && path_edges != 0U) path_edges--;
529	    if (first > document->edge_count ||
530	        path_edges > document->edge_count - first) {
531	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_INVALID_ARGUMENT,
532	             traversal->tokens[element].name.offset);
533	        return false;
534	    }
535	    if (path_edges == 0U) return true;
536	    /* Re-read edges by index after every emission: it may reallocate the array. */
537	    const geom_edge start = document->edges[first];
538	    if (!emit_marker(traversal, shape, style, SVG_CSS_MARKER_START,
539	            MARKER_POSITION_START, start.a, direction_angle(start),
540	            transform, render_depth)) return false;
541	    for (size_t i = 0U; i + 1U < path_edges; ++i) {
542	        const geom_edge incoming = document->edges[first + i];
543	        const geom_edge outgoing = document->edges[first + i + 1U];
544	        if (!emit_mid_marker(traversal, shape, style, incoming.b,
545	                incoming, outgoing, transform, render_depth)) return false;
546	    }
547	    const geom_edge end = document->edges[first + path_edges - 1U];
548	    return emit_marker(traversal, shape, style, SVG_CSS_MARKER_END,
549	        MARKER_POSITION_END, end.b, direction_angle(end), transform, render_depth);
550	}
551	
552	bool svg_shape_traverse_attach_markers(shape_traversal *traversal,
553	                                       size_t element, size_t first_shape,
554	                                       size_t end_shape,
555	                                       const svg_css_paint *style,
556	                                       size_t render_depth)
557	{
558	    if (traversal == NULL || style == NULL || first_shape > end_shape ||
559	        end_shape > traversal->builder.doc->shape_count) {
560	        fail(traversal == NULL ? NULL : traversal->diagnostic,
561	             SVG_SHAPE_ERROR_INVALID_ARGUMENT, 0U);
562	        return false;
563	    }
564	    bool marker_present = style->values[SVG_CSS_MARKER_START].present ||
565	        style->values[SVG_CSS_MARKER_MID].present ||
566	        style->values[SVG_CSS_MARKER_END].present;
567	    if (!marker_present || first_shape == end_shape) return true;
568	    if (end_shape - first_shape > 1024U) {
569	        fail(traversal->diagnostic, SVG_SHAPE_ERROR_LIMIT,
570	             traversal->tokens[element].name.offset);
571	        return false;
572	    }
573	    geom_affine transform = traversal->builder.doc->shape_sources[first_shape].transform;
574	    for (size_t shape = first_shape; shape < end_shape; ++shape) {
575	        if (svg_shape_traverse_element_name(traversal->source,
576	                &traversal->tokens[element], "path")) {
577	            if (!path_markers(traversal, shape, style, transform, render_depth))
578	                return false;
579	        } else if (!primitive_markers(traversal, element, shape, style,
580	                                      transform, render_depth)) return false;
581	    }
582	    return true;
583	}

