 10	#define CLIP_MAX_CHILDREN 64U
 11	#define CLIP_MAX_DEPTH 256U
 12	#define CLIP_MAX_REFERENCE_BYTES (64U * 1024U)
 13	#define CLIP_MAX_JOB_REFERENCE_BYTES (512U * 1024U)
 14	#define CLIP_WRAPPER_BUFFER_BYTES 192U
 15	#define CLIP_WRAPPER_LIMIT_BYTES 4096U
 16	/* Worst-case userSpaceOnUse wrapper: fixed text, two 10-digit %u values, four
 17	 * "-d.<16 digits>e-308" (24 byte) %.17g values, and the terminating NUL. */
 18	#define CLIP_WRAPPER_WORST_BYTES (12U + 10U + 11U + 3U + 2U + 2U * 10U + 4U * 24U + 1U)
 19	_Static_assert(CLIP_WRAPPER_BUFFER_BYTES <= CLIP_WRAPPER_LIMIT_BYTES,
 20	               "clip wrapper buffer exceeds the 4 KiB generated-syntax bound");
 21	_Static_assert(CLIP_WRAPPER_WORST_BYTES <= CLIP_WRAPPER_BUFFER_BYTES,
 22	               "worst-case clip wrapper must fit its buffer");
 23	#define CLIP_MAX_EDGES 65536U
 24	#define CLIP_CLONE_MAX_DEPTH 64U
 25	#define CLIP_CLONE_MAX_BYTES (64U * 1024U * 1024U)
