 27	struct svg_shape_clip {
 28	    svg_shape_document geometry;
 29	    uint8_t *source;
 30	    size_t source_length;
 31	    size_t owner_node;
 32	    bool owner_before_suffix;
 33	    size_t references;
 34	    struct svg_shape_clip *parent;
 35	    bool object_bounding_box;
 36	    double bounds[4];
