 40	static bool eq(base_bytes source, svg_xml_span span, const char *text)
 41	{
 42	    size_t length = strlen(text);
 43	    return span.offset <= source.len && span.length == length &&
 44	           length <= source.len - span.offset &&
 45	           memcmp(source.ptr + span.offset, text, length) == 0;
 46	}
