 48	static bool attr(base_bytes source, const svg_xml_token *tokens, size_t count,
 49	                 size_t element, const char *name, svg_xml_span *value)
 50	{
 51	    for (size_t i = element + 1U; i < count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
 52	        if (tokens[i].prefix.length == 0U && eq(source, tokens[i].local_name, name)) {
 53	            *value = tokens[i].value;
 54	            return true;
 55	        }
 56	    }
 57	    return false;
 58	}
