 60	static size_t element_end(const svg_xml_token *tokens, size_t count, size_t start)
 61	{
 62	    if (tokens[start].kind == SVG_XML_TOKEN_EMPTY_ELEMENT) return start;
 63	    for (size_t i = start + 1U; i < count; ++i) {
 64	        if (tokens[i].kind == SVG_XML_TOKEN_END_ELEMENT &&
 65	            tokens[i].depth == tokens[start].depth) return i;
 66	    }
 67	    return start;
 68	}
