 70	static svg_shape_error check_clip_child_style(
 71	    svg_css_sheet *css, base_bytes source, const svg_xml_token *tokens,
 72	    size_t token_count, size_t element, const svg_css_paint *parent,
 73	    svg_css_paint *computed, svg_shape_diagnostic *diagnostic)
 74	{
 75	    svg_css_error css_error = svg_css_compute(css, source, tokens, token_count,
 76	                                              element, parent, computed);
 77	    if (css_error != SVG_CSS_OK) {
 78	        svg_shape_error error = css_error == SVG_CSS_LIMIT ?
 79	            SVG_SHAPE_ERROR_LIMIT : css_error == SVG_CSS_OOM ?
 80	            SVG_SHAPE_ERROR_OOM : SVG_SHAPE_ERROR_UNSUPPORTED;
 81	        if (diagnostic != NULL)
 82	            *diagnostic = (svg_shape_diagnostic){error, tokens[element].name.offset};
 83	        return error;
 84	    }
 85	    for (size_t property = 0U; property < SVG_CSS_PROPERTY_COUNT; ++property) {
 86	        if (property != SVG_CSS_CLIP_RULE &&
 87	            computed->values[property].present) {
 88	            if (diagnostic != NULL)
 89	                *diagnostic = (svg_shape_diagnostic){
 90	                    SVG_SHAPE_ERROR_UNSUPPORTED,
 91	                    computed->values[property].span.offset};
 92	            return SVG_SHAPE_ERROR_UNSUPPORTED;
 93	        }
 94	    }
 95	    return SVG_SHAPE_ERROR_NONE;
 96	}
