 98	static svg_shape_error clip_rule_map(
 99	    svg_css_sheet *css, base_bytes source, const svg_xml_token *tokens,
100	    size_t token_count, size_t target, size_t end_token, size_t child_start,
101	    size_t child_length, uint8_t *rule_by_offset,
102	    svg_shape_diagnostic *diagnostic)
103	{
104	    svg_css_paint clip_style;
105	    svg_shape_error error = check_clip_child_style(css, source, tokens,
106	        token_count, target, NULL, &clip_style, diagnostic);
107	    if (error != SVG_SHAPE_ERROR_NONE) return error;
108	    svg_css_value rule_stack[CLIP_MAX_DEPTH] = {0};
109	    svg_xml_span rule = {0};
110	    if (svg_css_paint_value(&clip_style, SVG_CSS_CLIP_RULE, &rule)) {
111	        if (!svg_css_keyword_equals(source, rule, "nonzero") &&
112	            !svg_css_keyword_equals(source, rule, "evenodd")) {
113	            if (diagnostic != NULL)
114	                *diagnostic = (svg_shape_diagnostic){
115	                    SVG_SHAPE_ERROR_UNSUPPORTED, rule.offset};
116	            return SVG_SHAPE_ERROR_UNSUPPORTED;
117	        }
118	        rule_stack[0] = clip_style.values[SVG_CSS_CLIP_RULE];
119	    }
120	    for (size_t i = target + 1U; i < end_token; ++i) {
121	        if (tokens[i].kind != SVG_XML_TOKEN_START_ELEMENT &&
122	            tokens[i].kind != SVG_XML_TOKEN_EMPTY_ELEMENT) continue;
123	        if (tokens[i].depth <= tokens[target].depth) continue;
124	        size_t depth = (size_t)(tokens[i].depth - tokens[target].depth);
125	        if (depth >= CLIP_MAX_DEPTH) {
126	            if (diagnostic != NULL)
127	                *diagnostic = (svg_shape_diagnostic){
128	                    SVG_SHAPE_ERROR_LIMIT, tokens[i].name.offset};
129	            return SVG_SHAPE_ERROR_LIMIT;
130	        }
131	        svg_css_paint parent = {0};
132	        parent.values[SVG_CSS_CLIP_RULE] = rule_stack[depth - 1U];
133	        svg_css_paint computed;
134	        error = check_clip_child_style(css, source, tokens, token_count, i,
135	                                       &parent, &computed, diagnostic);
136	        if (error != SVG_SHAPE_ERROR_NONE) return error;
137	        rule = (svg_xml_span){0};
138	        if (svg_css_paint_value(&computed, SVG_CSS_CLIP_RULE, &rule) &&
139	            !svg_css_keyword_equals(source, rule, "nonzero") &&
140	            !svg_css_keyword_equals(source, rule, "evenodd")) {
141	            if (diagnostic != NULL)
142	                *diagnostic = (svg_shape_diagnostic){
143	                    SVG_SHAPE_ERROR_UNSUPPORTED, rule.offset};
144	            return SVG_SHAPE_ERROR_UNSUPPORTED;
145	        }
146	        rule_stack[depth] = computed.values[SVG_CSS_CLIP_RULE];
147	        size_t offset = tokens[i].source.offset;
148	        if (offset < child_start || offset - child_start >= child_length) {
149	            if (diagnostic != NULL)
150	                *diagnostic = (svg_shape_diagnostic){
151	                    SVG_SHAPE_ERROR_XML, tokens[i].name.offset};
152	            return SVG_SHAPE_ERROR_XML;
153	        }
154	        rule_by_offset[offset - child_start] =
155	            svg_css_paint_value(&computed, SVG_CSS_CLIP_RULE, &rule) &&
156	            svg_css_keyword_equals(source, rule, "evenodd") ? 1U : 0U;
157	    }
158	    return SVG_SHAPE_ERROR_NONE;
159	}
