340	bool svg_clip_contains(const svg_shape_clip *clip, double x, double y)
341	{
342	    if (clip == NULL) return true;
343	    double root_x = x, root_y = y;
344	    geom_point local;
345	    if (!geom_affine_map_point(clip->user_inverse, (geom_point){x, y}, &local))
346	        return false;
347	    x = local.x;
348	    y = local.y;
349	    if (clip->object_bounding_box) {
350	        if (clip->bounds[2] <= clip->bounds[0] ||
351	            clip->bounds[3] <= clip->bounds[1]) return false;
352	        x = (x - clip->bounds[0]) / (clip->bounds[2] - clip->bounds[0]);
353	        y = (y - clip->bounds[1]) / (clip->bounds[3] - clip->bounds[1]);
354	    }
355	    bool inside = false;
356	    for (size_t i = 0U; i < clip->geometry.shape_count; ++i) {
357	        if (clip->geometry.shape_filled[i] && point_inside(&clip->geometry, i, x, y)) {
358	            inside = true;
359	            break;
360	        }
361	    }
362	    return inside && svg_clip_contains(clip->parent, root_x, root_y);
363	}
