365	static bool clip_local_to_document(const svg_shape_clip *clip,
366	                                   geom_affine local_to_document,
367	                                   geom_point point, geom_point *out)
368	{
369	    if (clip->object_bounding_box) {
370	        point.x = clip->bounds[0] + point.x *
371	                  (clip->bounds[2] - clip->bounds[0]);
372	        point.y = clip->bounds[1] + point.y *
373	                  (clip->bounds[3] - clip->bounds[1]);
374	    }
375	    return geom_affine_map_point(local_to_document, point, out);
376	}
