378	bool svg_clip_visit_boundary_edges(const svg_shape_clip *clip,
379	                                   svg_clip_boundary_edge_visitor visitor,
380	                                   void *context, bool *mapping_valid)
381	{
382	    if (mapping_valid != NULL) *mapping_valid = true;
383	    if (visitor == NULL) return false;
384	    for (const svg_shape_clip *current = clip; current != NULL;
385	         current = current->parent) {
386	        geom_affine local_to_document;
387	        if (!svg_shape_affine_inverse(current->user_inverse,
388	                                      &local_to_document)) {
389	            if (mapping_valid != NULL) *mapping_valid = false;
390	            return true;
391	        }
392	        const svg_shape_document *geometry = &current->geometry;
393	        for (size_t shape = 0U; shape < geometry->shape_count; shape++) {
394	            if (!geometry->shape_filled[shape]) continue;
395	            size_t first = geometry->shape_edge_start[shape];
396	            size_t end = first + geometry->shape_edge_count[shape];
397	            for (size_t edge_index = first; edge_index < end; edge_index++) {
398	                geom_edge edge = geometry->edges[edge_index];
399	                if (!clip_local_to_document(current, local_to_document,
400	                                            edge.a, &edge.a) ||
401	                    !clip_local_to_document(current, local_to_document,
402	                                            edge.b, &edge.b)) {
403	                    if (mapping_valid != NULL) *mapping_valid = false;
404	                    return true;
405	                }
406	                if (!visitor(context, edge)) return false;
407	            }
408	        }
409	    }
410	    return true;
411	}
412	
413	bool svg_clip_boundary_work_counts(const svg_shape_clip *clip,
414	                                   svg_clip_work_counts *out)
415	{
416	    if (out == NULL) return false;
417	    *out = (svg_clip_work_counts){0};
418	    for (const svg_shape_clip *current = clip; current != NULL;
419	         current = current->parent) {
420	        if (out->chain_elements == SIZE_MAX ||
421	            current->geometry.shape_count > SIZE_MAX - out->child_shapes ||
422	            current->geometry.edge_count > SIZE_MAX - out->edges) return false;
423	        out->chain_elements++;
424	        out->child_shapes += current->geometry.shape_count;
425	        out->edges += current->geometry.edge_count;
426	    }
427	    return true;
428	}
429	
430	size_t svg_clip_work_units(const svg_shape_clip *clip)
431	{
432	    svg_clip_work_counts counts;
433	    if (!svg_clip_boundary_work_counts(clip, &counts) ||
434	        counts.child_shapes > SIZE_MAX - counts.chain_elements) return SIZE_MAX;
435	    size_t units = counts.chain_elements + counts.child_shapes;
436	    if (counts.edges > SIZE_MAX - units) return SIZE_MAX;
437	    return units + counts.edges;
438	}
