440	void svg_clip_destroy(svg_shape_clip *clip)
441	{
442	    if (clip == NULL) return;
443	    if (clip->references > 1U) { clip->references--; return; }
444	    svg_shape_clip *parent = clip->parent;
445	    svg_shape_document_destroy(&clip->geometry);
446	    svg_shape_free(clip->source);
447	    svg_shape_free(clip);
448	    svg_clip_destroy(parent);
449	}
450	
451	bool svg_clip_retain(svg_shape_clip *clip)
452	{
453	    if (clip == NULL || clip->references == SIZE_MAX) return false;
454	    clip->references++;
455	    return true;
456	}
457	
458	static bool clone_bytes(size_t count, size_t stride, size_t *bytes)
459	{
460	    if (count != 0U && stride > SIZE_MAX / count) return false;
461	    *bytes = count * stride;
462	    return true;
463	}
464	
465	static bool clone_array(const void *source, size_t count, size_t stride,
466	                        size_t *total, bool *limit, void **out)
467	{
468	    size_t bytes = 0U;
469	    if (!clone_bytes(count, stride, &bytes) ||
470	        bytes > CLIP_CLONE_MAX_BYTES - *total) {
471	        *limit = true;
472	        return false;
473	    }
474	    if (bytes == 0U) {
475	        *out = NULL;
476	        return true;
477	    }
478	    void *copy = svg_shape_malloc(bytes);
479	    if (copy == NULL) return false;
480	    memcpy(copy, source, bytes);
481	    *total += bytes;
482	    *out = copy;
483	    return true;
484	}
485	
486	static svg_shape_clip *clone_clip_chain(const svg_shape_clip *source,
487	                                        size_t depth, size_t *total,
488	                                        bool *limit)
489	{
490	    if (source == NULL || total == NULL || limit == NULL ||
491	        depth >= CLIP_CLONE_MAX_DEPTH) {
492	        if (limit != NULL) *limit = true;
493	        return NULL;
494	    }
495	    if (sizeof(svg_shape_clip) > CLIP_CLONE_MAX_BYTES - *total) {
496	        *limit = true;
497	        return NULL;
498	    }
499	    svg_shape_clip *copy = svg_shape_calloc(1U, sizeof(*copy));
500	    if (copy == NULL) return NULL;
501	    *total += sizeof(*copy);
502	    copy->references = 1U;
503	    copy->owner_node = source->owner_node;
504	    copy->owner_before_suffix = source->owner_before_suffix;
505	    copy->object_bounding_box = source->object_bounding_box;
506	    copy->user_inverse = source->user_inverse;
507	    memcpy(copy->bounds, source->bounds, sizeof(copy->bounds));
508	    if (!clone_array(source->source, source->source_length, 1U, total, limit,
509	                     (void **)&copy->source)) goto fail;
510	    copy->source_length = source->source_length;
511	    svg_shape_document *dst = &copy->geometry;
512	    const svg_shape_document *src = &source->geometry;
513	    dst->shape_count = src->shape_count;
514	    dst->edge_count = src->edge_count;
515	    if (!clone_array(src->edges, src->edge_count, sizeof(*src->edges), total, limit,
516	                     (void **)&dst->edges) ||
517	        !clone_array(src->shape_evenodd, src->shape_count,
518	                     sizeof(*src->shape_evenodd), total, limit,
519	                     (void **)&dst->shape_evenodd) ||
520	        !clone_array(src->shape_filled, src->shape_count,
521	                     sizeof(*src->shape_filled), total, limit,
522	                     (void **)&dst->shape_filled) ||
523	        !clone_array(src->shape_edge_start, src->shape_count,
524	                     sizeof(*src->shape_edge_start), total, limit,
525	                     (void **)&dst->shape_edge_start) ||
526	        !clone_array(src->shape_edge_count, src->shape_count,
527	                     sizeof(*src->shape_edge_count), total, limit,
528	                     (void **)&dst->shape_edge_count)) goto fail;
529	    if (source->parent != NULL) {
530	        copy->parent = clone_clip_chain(source->parent, depth + 1U, total,
531	                                        limit);
532	        if (copy->parent == NULL) goto fail;
533	    }
534	    return copy;
535	fail:
536	    svg_clip_destroy(copy);
537	    return NULL;
538	}
539	
540	svg_shape_clip *svg_clip_clone(const svg_shape_clip *clip,
541	                               size_t *total_bytes, bool *limit)
542	{
543	    if (total_bytes == NULL || limit == NULL) return NULL;
544	    *limit = false;
545	    return clone_clip_chain(clip, 0U, total_bytes, limit);
546	}
547	
548	void svg_clip_update_owner(svg_shape_clip *clip, size_t owner_node,
549	                           geom_affine user_inverse,
550	                           geom_affine attribute_inverse,
551	                           const double local_bounds[4])
552	{
553	    size_t depth = 0U;
554	    for (svg_shape_clip *current = clip; current != NULL &&
555	         depth++ < CLIP_CLONE_MAX_DEPTH; current = current->parent) {
556	        if (current->owner_node != owner_node) continue;
557	        geom_affine inverse = current->owner_before_suffix ?
558	                              attribute_inverse : user_inverse;
559	        if (!geom_affine_valid(inverse)) continue;
560	        current->user_inverse = inverse;
561	        if (local_bounds != NULL && current->object_bounding_box &&
562	            isfinite(local_bounds[0]) && isfinite(local_bounds[1]) &&
563	            isfinite(local_bounds[2]) && isfinite(local_bounds[3]) &&
564	            local_bounds[2] >= local_bounds[0] &&
565	            local_bounds[3] >= local_bounds[1])
566	            memcpy(current->bounds, local_bounds, sizeof(current->bounds));
567	    }
568	}
569	
570	bool svg_clip_local_bounds(const svg_shape_document *document,
571	                           size_t first_edge, size_t edge_count,
572	                           geom_affine user_inverse, double bounds[4])
573	{
574	    if (document == NULL || bounds == NULL || edge_count == 0U ||
575	        first_edge > document->edge_count ||
576	        edge_count > document->edge_count - first_edge) return false;
577	    geom_point first;
578	    if (!geom_affine_map_point(user_inverse, document->edges[first_edge].a,
579	                               &first)) return false;
580	    bounds[0] = bounds[2] = first.x;
581	    bounds[1] = bounds[3] = first.y;
582	    for (size_t i = first_edge; i < first_edge + edge_count; ++i) {
583	        geom_point points[2] = {document->edges[i].a, document->edges[i].b};
584	        for (size_t j = 0U; j < 2U; ++j) {
585	            geom_point local;
586	            if (!geom_affine_map_point(user_inverse, points[j], &local))
587	                return false;
588	            if (local.x < bounds[0]) bounds[0] = local.x;
589	            if (local.y < bounds[1]) bounds[1] = local.y;
590	            if (local.x > bounds[2]) bounds[2] = local.x;
591	            if (local.y > bounds[3]) bounds[3] = local.y;
592	        }
593	    }
594	    return true;
595	}
596	
597	bool svg_clip_apply_group(svg_shape_document *document,
598	                          size_t first_shape, size_t end_shape,
599	                          svg_shape_clip *clip)
600	{
601	    if (document == NULL || clip == NULL || first_shape > end_shape ||
602	        end_shape > document->shape_count) return false;
603	    for (size_t i = first_shape; i < end_shape; ++i) {
604	        svg_shape_clip *root = document->clips[i];
605	        if (root == NULL) {
606	            if (!svg_clip_retain(clip)) return false;
607	            document->clips[i] = clip;
608	            continue;
609	        }
610	        svg_shape_clip *tail = root;
611	        while (true) {
612	            if (tail == clip) break;
613	            if (tail->parent == NULL) {
614	                if (!svg_clip_retain(clip)) return false;
615	                tail->parent = clip;
616	                break;
617	            }
618	            tail = tail->parent;
619	        }
620	    }
621	    return true;
622	}
623	
624	svg_shape_clip *svg_clip_create_rect(geom_point p0, geom_point p1,
625	                                    geom_point p2, geom_point p3,
626	                                    geom_affine user_inverse,
627	                                    size_t owner_node)
628	{
629	    const geom_point points[4] = {p0, p1, p2, p3};
630	    for (size_t i = 0U; i < 4U; ++i)
631	        if (!geom_finite_point(points[i])) return NULL;
632	    svg_shape_clip *clip = svg_shape_calloc(1U, sizeof(*clip));
633	    if (clip == NULL) return NULL;
634	    svg_shape_document *geometry = &clip->geometry;
635	    geometry->edges = svg_shape_calloc(4U, sizeof(*geometry->edges));
636	    geometry->shape_evenodd = svg_shape_calloc(1U, sizeof(*geometry->shape_evenodd));
637	    geometry->shape_filled = svg_shape_calloc(1U, sizeof(*geometry->shape_filled));
638	    geometry->shape_edge_start = svg_shape_calloc(1U, sizeof(*geometry->shape_edge_start));
639	    geometry->shape_edge_count = svg_shape_calloc(1U, sizeof(*geometry->shape_edge_count));
640	    if (geometry->edges == NULL || geometry->shape_evenodd == NULL ||
641	        geometry->shape_filled == NULL || geometry->shape_edge_start == NULL ||
642	        geometry->shape_edge_count == NULL) {
643	        svg_clip_destroy(clip);
644	        return NULL;
645	    }
646	    for (size_t i = 0U; i < 4U; ++i)
647	        geometry->edges[i] = (geom_edge){points[i], points[(i + 1U) % 4U]};
648	    geometry->shape_count = 1U;
649	    geometry->edge_count = 4U;
650	    geometry->shape_edge_count[0] = 4U;
651	    geometry->shape_filled[0] = true;
652	    clip->references = 1U;
653	    clip->user_inverse = user_inverse;
654	    clip->owner_node = owner_node;
655	    clip->owner_before_suffix = true;
656	    return clip;
657	}

