 56	
 57	pub fn parse_attributes(
 58	    source: &[u8],
 59	    tokens: &[XmlToken],
 60	    element: usize,
 61	) -> Result<MarkerAttributes> {
 62	    parse_attributes_for_viewport(source, tokens, element, [1.0, 1.0])
 63	}
 64	
 65	/// Parses marker lengths using the active viewport, as the definition walker
 66	/// does for percentage marker dimensions.
 67	pub fn parse_attributes_for_viewport(
 68	    source: &[u8],
 69	    tokens: &[XmlToken],
 70	    element: usize,
 71	    viewport: [f64; 2],
 72	) -> Result<MarkerAttributes> {
 73	    if viewport.iter().any(|v| !v.is_finite() || *v <= 0.0) {
 74	        return Err(number(tokens.get(element).map_or(0, |t| t.name.offset)));
 75	    }
 76	    const ALLOWED: &[&[u8]] = &[
 77	        b"id",
 78	        b"class",
 79	        b"style",
 80	        b"markerWidth",
 81	        b"markerHeight",
 82	        b"refX",
 83	        b"refY",
 84	        b"markerUnits",
 85	        b"orient",
 86	        b"viewBox",
 87	        b"preserveAspectRatio",
 88	        b"overflow",
 89	    ];
 90	    for a in tokens
 91	        .get(element + 1..)
 92	        .ok_or_else(|| bad(0))?
 93	        .iter()
 94	        .take_while(|t| t.kind == TokenKind::Attribute)
 95	    {
 96	        if a.prefix.length != 0
 97	            || !ALLOWED.contains(&span_bytes(source, a.local_name).unwrap_or_default())
 98	        {
 99	            return Err(unsupported(a.name.offset));
100	        }
101	        if span_bytes(source, a.local_name) == Some(b"overflow") {
102	            let b = span_bytes(source, a.value).unwrap_or_default();
103	            if !b.eq_ignore_ascii_case(b"visible") && !b.eq_ignore_ascii_case(b"hidden") {
104	                return Err(unsupported(a.value.offset));
105	            }
106	        }
107	    }
108	    let width = attr(source, tokens, element, b"markerWidth")
109	        .map(|s| parse_length(source, s, viewport[0]))
110	        .transpose()?
111	        .unwrap_or(3.);
112	    let height = attr(source, tokens, element, b"markerHeight")
113	        .map(|s| parse_length(source, s, viewport[1]))
114	        .transpose()?
115	        .unwrap_or(3.);
116	    if width <= 0. || height <= 0. {
117	        return Err(number(tokens[element].name.offset));
118	    }
119	    if width > 4096. || height > 4096. {
120	        return Err(limit(tokens[element].name.offset));
121	    }
122	    let ref_x = attr(source, tokens, element, b"refX")
123	        .map(|s| parse_length(source, s, width))
124	        .transpose()?
125	        .unwrap_or(0.);
126	    let ref_y = attr(source, tokens, element, b"refY")
127	        .map(|s| parse_length(source, s, height))
128	        .transpose()?
129	        .unwrap_or(0.);
130	    let stroke_width_units = match attr(source, tokens, element, b"markerUnits")
131	        .map(|s| span_bytes(source, s).unwrap_or_default())
132	    {
133	        None | Some(b"strokeWidth") => true,
134	        Some(b"userSpaceOnUse") => false,
135	        _ => {
136	            return Err(unsupported(
137	                attr(source, tokens, element, b"markerUnits")
138	                    .unwrap()
139	                    .offset,
140	            ));
141	        }
142	    };
143	    let orient = if let Some(s) = attr(source, tokens, element, b"orient") {
144	        parse_orient(source, s)?
145	    } else {
146	        MarkerOrient::Angle(0.)
147	    };
148	    let mut content = affine_identity();
149	    let child_viewport = [width, height];
150	    if let Some(s) = attr(source, tokens, element, b"viewBox") {
151	        let v = number_list(source, s, 4)?;
152	        if v.len() != 4 || v[2] <= 0. || v[3] <= 0. {
153	            return Err(Diagnostic {
154	                kind: ErrorKind::Viewport,
155	                offset: s.offset,
156	            });
157	        }
158	        let aspect = if let Some(a) = attr(source, tokens, element, b"preserveAspectRatio") {
159	            let end = a.offset + a.length;
160	            vexel_svg_values::parse_preserve_aspect(
161	                source,
162	                vexel_base::Span {
163	                    start: a.offset,
164	                    end,
165	                },
166	            )
167	            .map_err(|e| Diagnostic {
168	                kind: ErrorKind::Unsupported,
169	                offset: e.offset,
170	            })?
171	        } else {
172	            vexel_svg_values::Aspect {
173	                align_x: 0.5,
174	                align_y: 0.5,
175	                none: false,
176	                slice: false,
177	                set: true,
178	            }
179	        };
180	        content = vexel_svg_values::viewbox_transform(
181	            v[0], v[1], v[2], v[3], 0., 0., width, height, aspect,
182	        )
183	        .map_err(|_| Diagnostic {
184	            kind: ErrorKind::Viewport,
185	            offset: s.offset,
186	        })?;
187	        let Some(reference) =
188	            vexel_geometry::affine_map_point(content, Point { x: ref_x, y: ref_y })
189	        else {
190	            return Err(Diagnostic {
191	                kind: ErrorKind::Viewport,
192	                offset: s.offset,
193	            });
194	        };
195	        return Ok(MarkerAttributes {
196	            width,
197	            height,
198	            ref_x: reference.x,
199	            ref_y: reference.y,
200	            stroke_width_units,
201	            orient,
202	            content,
203	            child_viewport: [v[2], v[3]],
204	        });
205	    }
206	    Ok(MarkerAttributes {
207	        width,
208	        height,
209	        ref_x,
210	        ref_y,
211	        stroke_width_units,
212	        orient,
213	        content,
214	        child_viewport,
215	    })
216	}
217	pub fn direction_angle(edge: Edge) -> f64 {
218	    (edge.b.y - edge.a.y).atan2(edge.b.x - edge.a.x)
219	}
220	pub fn middle_angle(incoming: Edge, outgoing: Edge) -> f64 {
221	    let first = direction_angle(incoming);
222	    let mut delta = (direction_angle(outgoing) - first) % (2.0 * PI);
223	    if delta > PI {
224	        delta -= 2.0 * PI;
225	    } else if delta < -PI {
226	        delta += 2.0 * PI;
227	    }
228	    first + delta * 0.5
229	}
230	pub fn element_scale(m: Affine) -> f64 {
231	    let xx = m.a * m.a + m.b * m.b;
232	    let yy = m.c * m.c + m.d * m.d;
233	    let xy = m.a * m.c + m.b * m.d;
234	    ((xx + yy + ((xx - yy) * (xx - yy) + 4. * xy * xy).sqrt()) * 0.5)
235	        .max(0.)
236	        .sqrt()
237	}
238	pub fn compose_marker_transform(
239	    position: Point,
240	    angle: f64,
241	    scale: f64,
242	    content: Affine,
243	    reference: Point,
244	) -> Option<Affine> {
245	    let tr = Affine {
246	        a: 1.,
247	        b: 0.,
248	        c: 0.,
249	        d: 1.,
250	        e: position.x,
251	        f: position.y,
252	    };
253	    let rot = Affine {
254	        a: angle.cos(),
255	        b: angle.sin(),
256	        c: -angle.sin(),
257	        d: angle.cos(),
258	        e: 0.,
259	        f: 0.,
260	    };
261	    let sc = Affine {
262	        a: scale,
263	        b: 0.,
264	        c: 0.,
265	        d: scale,
266	        e: 0.,
267	        f: 0.,
268	    };
269	    let sh = Affine {
270	        a: 1.,
271	        b: 0.,
272	        c: 0.,
273	        d: 1.,
274	        e: -reference.x,
275	        f: -reference.y,
276	    };
277	    let x = affine_compose(tr, rot)?;
278	    let x = affine_compose(x, sc)?;
279	    let x = affine_compose(x, sh)?;
280	    affine_compose(x, content)
281	}
282	fn parse_orient(source: &[u8], span: XmlSpan) -> Result<MarkerOrient> {
283	    let b = span_bytes(source, span).ok_or_else(|| bad(span.offset))?;
284	    if b.eq_ignore_ascii_case(b"auto") {
285	        return Ok(MarkerOrient::Auto);
286	    }
287	    if b.eq_ignore_ascii_case(b"auto-start-reverse") {
288	        return Ok(MarkerOrient::AutoStartReverse);
289	    }
290	    let mut first = 0usize;
291	    let mut last = b.len();
292	    while first < last && crate::ascii_space(b[first]) {
293	        first += 1;
294	    }
295	    while last > first && crate::ascii_space(b[last - 1]) {
296	        last -= 1;
297	    }
298	    if last - first >= 3 && &b[last - 3..last] == b"deg" {
299	        last -= 3;
300	        while last > first && crate::ascii_space(b[last - 1]) {
301	            last -= 1;
302	        }
303	    }
304	    if first == last {
305	        return Err(number(span.offset));
306	    }
307	    let s = XmlSpan {
308	        offset: span
309	            .offset
310	            .checked_add(first)
311	            .ok_or_else(|| bad(span.offset))?,
312	        length: last - first,
313	    };
314	    Ok(MarkerOrient::Angle(crate::common::parse_number(
315	        source, s, 0.,
316	    )?))
317	}
318	fn bad(offset: usize) -> Diagnostic {
319	    Diagnostic {
320	        kind: ErrorKind::InvalidArgument,
321	        offset,
322	    }
323	}
324	fn number(offset: usize) -> Diagnostic {
325	    Diagnostic {
326	        kind: ErrorKind::Number,
327	        offset,
328	    }
329	}
330	fn unsupported(offset: usize) -> Diagnostic {
331	    Diagnostic {
332	        kind: ErrorKind::Unsupported,
333	        offset,
334	    }
335	}
336	fn limit(offset: usize) -> Diagnostic {
