109	pub(super) fn validate_clip_styles<'src>(
110	    ctx: &mut DefinitionContext<'src, '_>,
111	    root: usize,
112	    end: usize,
113	    root_style: &CssPaint<'src>,
114	    control: &mut dyn WorkControl,
115	) -> Result<()> {
116	    let root_depth = ctx.shared.tokens().get(root).ok_or_else(|| bad(0))?.depth;
117	    let mut stack = Vec::new();
118	    stack.try_reserve(64).map_err(|_| oom(0))?;
119	    stack.push((root_depth, root_style.clone()));
120	    for i in root + 1..end {
121	        let token = *ctx.shared.tokens().get(i).ok_or_else(|| bad(0))?;
122	        control.charge(WorkKind::TokenVisit, 1).map_err(stopped)?;
123	        if token.kind == TokenKind::EndElement {
124	            while stack.last().is_some_and(|(depth, _)| *depth >= token.depth) {
125	                stack.pop();
126	            }
127	            continue;
128	        }
129	        if !matches!(
130	            token.kind,
131	            TokenKind::StartElement | TokenKind::EmptyElement
132	        ) {
133	            continue;
134	        }
135	        while stack.last().is_some_and(|(depth, _)| *depth >= token.depth) {
136	            stack.pop();
137	        }
138	        let parent = stack.last().map(|(_, style)| style);
139	        let style = ctx.shared.compute_style(ElementId(i), parent, control)?;
140	        check_clip_style(&style, token.name.offset)?;
141	        if token.kind == TokenKind::StartElement {
142	            if stack.len() >= crate::clip::MAX_CLIP_DEPTH {
143	                return Err(crate::limit(LimitKind::Depth, token.name.offset));
144	            }
145	            stack.try_reserve(1).map_err(|_| oom(token.name.offset))?;
146	            stack.push((token.depth, style));
147	        }
148	    }
149	    Ok(())
150	}
151	pub(super) fn check_clip_style(style: &CssPaint<'_>, _offset: usize) -> Result<()> {
152	    for p in Property::ALL {
153	        if p != Property::ClipRule && style.value(p).is_some() {
154	            return Err(unsupported(style.value(p).unwrap().span.offset));
155	        }
156	    }
157	    if let Some(v) = style.value(Property::ClipRule) {
158	        if !v.bytes.eq_ignore_ascii_case(b"nonzero") && !v.bytes.eq_ignore_ascii_case(b"evenodd") {
159	            return Err(unsupported(v.span.offset));
160	        }
161	    }
162	    Ok(())
163	}
