445	/// Marker placements over original parser path segments; only authored segment
446	/// boundaries receive mid markers, even when a curve flattened to many edges.
447	pub fn path_placements(
448	    edges: &[Edge],
449	    segments: &[vexel_svg_path::PathSegment],
450	    attributes: MarkerAttributes,
451	    transform: Affine,
452	    stroke_width: f64,
453	) -> Result<Vec<MarkerPlacement>> {
454	    let scale = marker_scale(attributes, transform, stroke_width);
455	    let mut out = Vec::new();
456	    out.try_reserve(edges.len().min(MAX_MARKER_INSTANCES))
457	        .map_err(|_| oom(0))?;
458	    let mut first = None;
459	    let mut last = None;
460	    for segment in segments {
461	        let command = segment.command.to_ascii_uppercase();
462	        if command == b'M' {
463	            flush(&mut out, &mut first, &mut last, attributes, scale)?;
464	        }
465	        if segment.edge_count == 0 {
466	            continue;
467	        }
468	        let end = segment
469	            .first_edge
470	            .checked_add(segment.edge_count)
471	            .ok_or_else(|| bad(segment.source.start))?;
472	        let path = edges
473	            .get(segment.first_edge..end)
474	            .ok_or_else(|| bad(segment.source.start))?;
475	        let a = path[0];
476	        let b = *path.last().ok_or_else(|| bad(segment.source.start))?;
477	        if let Some(incoming) = last {
478	            push(
479	                &mut out,
480	                MarkerPosition::Middle,
481	                incoming.b,
482	                middle_angle(incoming, a),
483	                attributes,
484	                scale,
485	            )?;
486	        } else {
487	            first = Some(a);
488	            push(
489	                &mut out,
490	                MarkerPosition::Start,
491	                a.a,
492	                oriented(a, MarkerPosition::Start, attributes.orient),
493	                attributes,
494	                scale,
495	            )?;
496	        }
497	        last = Some(b);
498	        if command == b'Z' {
499	            flush(&mut out, &mut first, &mut last, attributes, scale)?;
500	        }
501	    }
502	    flush(&mut out, &mut first, &mut last, attributes, scale)?;
503	    Ok(out)
504	}
505	/// Primitive marker placement follows the owned decoder's line/polyline/polygon edge ranges.
506	pub fn primitive_placements(
507	    edges: &[Edge],
508	    polyline: bool,
509	    attributes: MarkerAttributes,
510	    transform: Affine,
511	    stroke_width: f64,
512	) -> Result<Vec<MarkerPlacement>> {
513	    let count = edges.len().saturating_sub(usize::from(polyline));
514	    if count == 0 {
515	        return Ok(Vec::new());
516	    }
517	    if count > MAX_MARKER_INSTANCES.saturating_sub(1) {
518	        return Err(limit(0));
519	    }
520	    let used = &edges[..count];
521	    let scale = marker_scale(attributes, transform, stroke_width);
522	    let mut out = Vec::new();
523	    out.try_reserve_exact(count.saturating_add(1))
524	        .map_err(|_| oom(0))?;
525	    let first = used[0];
526	    push(
527	        &mut out,
528	        MarkerPosition::Start,
529	        first.a,
530	        oriented(first, MarkerPosition::Start, attributes.orient),
531	        attributes,
532	        scale,
533	    )?;
534	    for pair in used.windows(2) {
535	        push(
536	            &mut out,
537	            MarkerPosition::Middle,
538	            pair[0].b,
539	            middle_angle(pair[0], pair[1]),
540	            attributes,
541	            scale,
542	        )?;
543	    }
544	    let last = *used.last().unwrap();
545	    push(
546	        &mut out,
547	        MarkerPosition::End,
548	        last.b,
549	        oriented(last, MarkerPosition::End, attributes.orient),
550	        attributes,
551	        scale,
552	    )?;
553	    Ok(out)
554	}
555	fn marker_scale(a: MarkerAttributes, transform: Affine, width: f64) -> f64 {
556	    if a.stroke_width_units {
557	        let v = width * element_scale(transform);
558	        if v.is_finite() && v > 0. { v } else { 1. }
559	    } else {
560	        1.
561	    }
562	}
563	fn oriented(edge: Edge, position: MarkerPosition, orient: MarkerOrient) -> f64 {
564	    match orient {
565	        MarkerOrient::Angle(d) => d * PI / 180.,
566	        MarkerOrient::Auto => direction_angle(edge),
567	        MarkerOrient::AutoStartReverse => {
568	            direction_angle(edge)
569	                + if position == MarkerPosition::Start {
570	                    PI
571	                } else {
572	                    0.
573	                }
574	        }
575	    }
576	}
577	fn push(
578	    out: &mut Vec<MarkerPlacement>,
579	    position: MarkerPosition,
580	    point: Point,
581	    angle: f64,
582	    a: MarkerAttributes,
583	    scale: f64,
584	) -> Result<()> {
585	    if out.len() >= MAX_MARKER_INSTANCES {
586	        return Err(limit(0));
587	    }
588	    let transform = compose_marker_transform(
589	        point,
590	        angle,
591	        scale,
592	        a.content,
593	        Point {
594	            x: a.ref_x,
595	            y: a.ref_y,
596	        },
597	    )
598	    .ok_or_else(|| number(0))?;
599	    out.try_reserve(1).map_err(|_| Diagnostic {
600	        kind: ErrorKind::OutOfMemory,
601	        offset: 0,
602	    })?;
603	    out.push(MarkerPlacement {
604	        position,
605	        point,
606	        angle,
607	        transform,
608	    });
609	    Ok(())
610	}
611	const MAX_MARKER_INSTANCES: usize = 1024;
612	fn oom(offset: usize) -> Diagnostic {
613	    Diagnostic {
614	        kind: ErrorKind::OutOfMemory,
615	        offset,
616	    }
617	}
618	fn flush(
619	    out: &mut Vec<MarkerPlacement>,
620	    first: &mut Option<Edge>,
621	    last: &mut Option<Edge>,
622	    a: MarkerAttributes,
623	    scale: f64,
624	) -> Result<()> {
625	    if first.is_some() {
626	        if let Some(end) = *last {
627	            push(
628	                out,
629	                MarkerPosition::End,
630	                end.b,
631	                oriented(end, MarkerPosition::End, a.orient),
632	                a,
633	                scale,
634	            )?;
635	        }
636	    }
637	    *first = None;
638	    *last = None;
639	    Ok(())
640	}

