180	pub(crate) fn pattern_descriptor_from_mapping(
181	    source: &[u8],
182	    tokens: &[XmlToken],
183	    mapping: PatternMapping,
184	    bounds: [f64; 4],
185	    transform: Affine,
186	    viewport: Viewport,
187	) -> Result<PatternDescriptor> {
188	    let element = mapping.definition.0;
189	    let token = tokens.get(element).ok_or_else(|| crate::invalid(0))?;
190	    let mut density_x = viewport.width as f64 / viewport.view_width;
191	    let mut density_y = viewport.height as f64 / viewport.view_height;
192	    if !viewport.aspect.none {
193	        let density = if viewport.aspect.slice {
194	            density_x.max(density_y)
195	        } else {
196	            density_x.min(density_y)
197	        };
198	        density_x = density;
199	        density_y = density;
200	    }
201	    let transform_scale = transform
202	        .a
203	        .hypot(transform.b)
204	        .max(transform.c.hypot(transform.d));
205	    let width = (mapping.tile_width * density_x * transform_scale * mapping.pattern_scale * 4.)
206	        .ceil()
207	        .max(1.);
208	    let height = (mapping.tile_height * density_y * transform_scale * mapping.pattern_scale * 4.)
209	        .ceil()
210	        .max(1.);
211	    if !width.is_finite()
212	        || !height.is_finite()
213	        || width > 4096.
214	        || height > 4096.
215	        || width * height > 1_048_576.
216	    {
217	        return Err(crate::limit(LimitKind::Patterns, token.name.offset));
218	    }
219	    let content_object = unit_flag(source, tokens, element, b"patternContentUnits", false)?;
220	    let mut content = if let Some(span) = attr(source, tokens, element, b"viewBox") {
221	        let values = crate::common::number_list(source, span, 4).map_err(|_| Diagnostic {
222	            kind: ErrorKind::Viewport,
223	            offset: span.offset,
224	        })?;
225	        if values.len() != 4 || values[2] <= 0. || values[3] <= 0. {
226	            return Err(Diagnostic {
227	                kind: ErrorKind::Viewport,
228	                offset: span.offset,
229	            });
230	        }
231	        let aspect = if let Some(a) = attr(source, tokens, element, b"preserveAspectRatio") {
232	            let end = a
233	                .offset
234	                .checked_add(a.length)
235	                .ok_or_else(|| crate::invalid(a.offset))?;
236	            vexel_svg_values::parse_preserve_aspect(
237	                source,
238	                vexel_base::Span {
239	                    start: a.offset,
240	                    end,
241	                },
242	            )
243	            .map_err(|e| unsupported(e.offset))?
244	        } else {
245	            vexel_svg_values::Aspect {
246	                align_x: 0.5,
247	                align_y: 0.5,
248	                none: false,
249	                slice: false,
250	                set: true,
251	            }
252	        };
253	        vexel_svg_values::viewbox_transform(
254	            values[0],
255	            values[1],
256	            values[2],
257	            values[3],
258	            0.,
259	            0.,
260	            mapping.tile_width,
261	            mapping.tile_height,
262	            aspect,
263	        )
264	        .map_err(|_| Diagnostic {
265	            kind: ErrorKind::Viewport,
266	            offset: span.offset,
267	        })?
268	    } else if content_object {
269	        Affine {
270	            a: bounds[2] - bounds[0],
271	            d: bounds[3] - bounds[1],
272	            e: bounds[0],
273	            f: bounds[1],
274	            ..affine_identity()
275	        }
276	    } else {
277	        affine_identity()
278	    };
279	    if attr(source, tokens, element, b"viewBox").is_none() {
280	        content = affine_compose(
281	            Affine {
282	                e: -mapping.tile_origin[0],
283	                f: -mapping.tile_origin[1],
284	                ..affine_identity()
285	            },
286	            content,
287	        )
288	        .ok_or_else(|| crate::limit(LimitKind::Arithmetic, token.name.offset))?;
289	    }
290	    Ok(PatternDescriptor {
291	        definition: mapping.definition,
292	        width: width as u32,
293	        height: height as u32,
294	        tile_width: mapping.tile_width,
295	        tile_height: mapping.tile_height,
296	        content_transform: content,
297	        error_offset: token.name.offset,
298	    })
299	}
