 19	pub fn create_rect(
 20	    points: [Point; 4],
 21	    user_inverse: Affine,
 22	    owner_node: Option<TransformId>,
 23	    builder: &mut SceneBuilder,
 24	    scene: SceneId,
 25	    control: &mut dyn WorkControl,
 26	) -> Result<ClipId> {
 27	    if !affine_valid(user_inverse) || points.iter().any(|p| !p.x.is_finite() || !p.y.is_finite()) {
 28	        return Err(Diagnostic {
 29	            kind: ErrorKind::InvalidArgument,
 30	            offset: 0,
 31	        });
 32	    }
 33	    if 4 > MAX_CLIP_EDGES {
 34	        return Err(limit());
 35	    }
 36	    let mut edges = Vec::new();
 37	    edges.try_reserve_exact(4).map_err(|_| oom())?;
 38	    for i in 0..4 {
 39	        edges.push(Edge {
 40	            a: points[i],
 41	            b: points[(i + 1) % 4],
 42	        });
 43	    }
 44	    let mut shapes = Vec::new();
 45	    shapes.try_reserve_exact(1).map_err(|_| oom())?;
 46	    shapes.push(ClipChild {
 47	        edges: TableRange { first: 0, count: 4 },
 48	        evenodd: false,
 49	        filled: true,
 50	    });
 51	    let (mut lo_x, mut lo_y, mut hi_x, mut hi_y) =
 52	        (points[0].x, points[0].y, points[0].x, points[0].y);
 53	    for p in points.iter().skip(1) {
 54	        lo_x = lo_x.min(p.x);
 55	        lo_y = lo_y.min(p.y);
 56	        hi_x = hi_x.max(p.x);
 57	        hi_y = hi_y.max(p.y);
 58	    }
 59	    builder.append_clip(
 60	        scene,
 61	        Clip {
 62	            geometry: ClipGeometry { edges, shapes },
 63	            parent: None,
 64	            owner_node,
 65	            owner_before_suffix: true,
 66	            object_bounding_box: false,
 67	            bounds: [lo_x, lo_y, hi_x, hi_y],
 68	            user_inverse,
 69	        },
 70	        control,
 71	    )
 72	}
