223	/// Appends a per-shape child clip and finalizes each new shape inside the caller's
224	/// real draft. Existing clip records remain immutable and shared safely.
225	pub fn apply_group(
226	    builder: &mut SceneBuilder,
227	    token: &DraftToken,
228	    scene: SceneId,
229	    shape_ids: &[ShapeId],
230	    clip: ClipId,
231	    control: &mut dyn WorkControl,
232	) -> Result<()> {
233	    if shape_ids.is_empty() {
234	        return Ok(());
235	    }
236	    if shape_ids.len() > MAX_CLIP_CLONE_BYTES / std::mem::size_of::<(ClipId, ClipId)>() {
237	        return Err(limit());
238	    }
239	    let mut root_cache = Vec::<(ClipId, ClipId)>::new();
240	    root_cache.try_reserve(shape_ids.len()).map_err(|_| oom())?;
241	    let mut copied_bytes = 0usize;
242	    for id in shape_ids {
243	        control.checkpoint().map_err(stopped)?;
244	        let old = builder
245	            .scene(scene)?
246	            .shape(*id)
247	            .copied()
248	            .ok_or_else(invalid)?;
249	        let appended = if let Some(old_root) = old.clip {
250	            if chain_contains(builder.scene(scene)?, old_root, clip, control)? {
251	                continue;
252	            }
253	            if let Some((_, copied_root)) =
254	                root_cache.iter().find(|(source, _)| *source == old_root)
255	            {
256	                *copied_root
257	            } else {
258	                let copied_root = append_clip_chain(
259	                    builder,
260	                    scene,

260	                    scene,
261	                    old_root,
262	                    Some(clip),
263	                    control,
264	                    &mut copied_bytes,
265	                )?;
266	                root_cache.push((old_root, copied_root));
267	                copied_root
268	            }
269	        } else {
270	            clip
271	        };
272	        let mut shape = old;
273	        shape.clip = Some(appended);
274	        builder.finalize_shape(token, *id, shape, control)?;
275	    }
276	    Ok(())
277	}
278	fn chain_contains(
279	    view: SceneView<'_>,
280	    root: ClipId,
281	    target: ClipId,
282	    control: &mut dyn WorkControl,
283	) -> Result<bool> {
284	    let mut next = Some(root);
285	    let mut depth = 0usize;
286	    while let Some(id) = next {
287	        control.checkpoint().map_err(stopped)?;
288	        if depth >= MAX_CLIP_CLONE_DEPTH {
289	            return Err(limit());
290	        }
291	        if id == target {
292	            return Ok(true);
293	        }
294	        let clip = view.clip(id).ok_or_else(invalid)?;
295	        control.charge(WorkKind::ClipChain, 1).map_err(stopped)?;
296	        next = clip.parent;
297	        depth += 1;
298	    }
299	    Ok(false)
300	}
301	fn append_clip_chain(
302	    builder: &mut SceneBuilder,
303	    scene: SceneId,
304	    root: ClipId,
305	    parent: Option<ClipId>,
306	    control: &mut dyn WorkControl,
307	    copied_bytes: &mut usize,
308	) -> Result<ClipId> {
309	    let mut chain = Vec::new();
310	    chain
311	        .try_reserve_exact(MAX_CLIP_CLONE_DEPTH)
312	        .map_err(|_| oom())?;
313	    let mut next = Some(root);
314	    while let Some(id) = next {
315	        control.checkpoint().map_err(stopped)?;
316	        if chain.len() >= MAX_CLIP_CLONE_DEPTH {
317	            return Err(limit());
318	        }
319	        let view = builder.scene(scene)?;
320	        let clip = view.clip(id).ok_or_else(invalid)?;
321	        let work = clip
322	            .geometry
323	            .edges
324	            .len()
325	            .checked_add(clip.geometry.shapes.len())
326	            .and_then(|n| n.checked_add(1))
327	            .ok_or_else(arithmetic)?;
328	        control
329	            .charge(
330	                WorkKind::ClipEdge,
331	                u64::try_from(work).map_err(|_| arithmetic())?,
332	            )
333	            .map_err(stopped)?;
334	        chain.push(id);
335	        next = clip.parent;
336	    }
337	    let mut parent = parent;
338	    let mut result = None;
339	    for id in chain.into_iter().rev() {
340	        let mut copy = {
341	            let view = builder.scene(scene)?;
342	            let source = view.clip(id).ok_or_else(invalid)?;
343	            clone_clip_geometry(source)?
344	        };
345	        copy.parent = parent;
346	        let actual = copy
347	            .geometry
348	            .edges
349	            .capacity()
350	            .checked_mul(std::mem::size_of::<Edge>())
351	            .and_then(|n| {
352	                copy.geometry
353	                    .shapes
354	                    .capacity()
355	                    .checked_mul(std::mem::size_of::<ClipChild>())
356	                    .and_then(|m| n.checked_add(m))
357	            })
358	            .ok_or_else(arithmetic)?;
359	        *copied_bytes = copied_bytes
360	            .checked_add(actual)
361	            .filter(|n| *n <= MAX_CLIP_CLONE_BYTES)
362	            .ok_or_else(limit)?;
363	        let appended = builder.append_clip(scene, copy, control)?;
364	        parent = Some(appended);
365	        result = Some(appended);
366	    }
367	    result.ok_or_else(invalid)
368	}
369	fn clone_clip_geometry(c: &Clip) -> Result<Clip> {
370	    let mut edges = Vec::new();
371	    edges
372	        .try_reserve_exact(c.geometry.edges.len())
373	        .map_err(|_| oom())?;
374	    edges.extend_from_slice(&c.geometry.edges);
375	    let mut shapes = Vec::new();
376	    shapes
377	        .try_reserve_exact(c.geometry.shapes.len())
378	        .map_err(|_| oom())?;
379	    shapes.extend_from_slice(&c.geometry.shapes);
380	    Ok(Clip {
381	        geometry: ClipGeometry { edges, shapes },
382	        parent: None,
383	        owner_node: c.owner_node,
384	        owner_before_suffix: c.owner_before_suffix,
385	        object_bounding_box: c.object_bounding_box,
386	        bounds: c.bounds,
387	        user_inverse: c.user_inverse,
388	    })
389	}
