 36	pub fn reference_value<'src>(
 37	    style: &CssPaint<'src>,
 38	    position: MarkerPosition,
 39	) -> Option<CssValue<'src>> {
 40	    let specific = match position {
 41	        MarkerPosition::Start => Property::MarkerStart,
