 38	pub fn parse_pattern_mapping(
 39	    source: &[u8],
 40	    tokens: &[XmlToken],
 41	    element: usize,
 42	    bounds: [f64; 4],
 43	    viewport: Viewport,
 44	    control: &mut dyn WorkControl,
 45	) -> Result<PatternMapping> {
 46	    let token = tokens.get(element).ok_or_else(|| crate::invalid(0))?;
 47	    let object = unit_flag(source, tokens, element, b"patternUnits", true)?;
 48	    let content_object = unit_flag(source, tokens, element, b"patternContentUnits", false)?;
 49	    let bounds_width = bounds[2] - bounds[0];
 50	    let bounds_height = bounds[3] - bounds[1];
 51	    if (object || content_object) && (bounds_width <= 0. || bounds_height <= 0.) {
 52	        return Err(unsupported(token.name.offset));
 53	    }
 54	    let refs = [viewport.view_width, viewport.view_height];
 55	    let mut values = [0.; 4];
 56	    for (i, name) in [b"x".as_slice(), b"y", b"width", b"height"]
 57	        .iter()
 58	        .enumerate()
 59	    {
 60	        if let Some(span) = attr(source, tokens, element, name) {
 61	            values[i] = if object {
 62	                bbox_number(source, span)?
 63	            } else {
 64	                parse_length(source, span, refs[i % 2])?
 65	            };
 66	        }
 67	    }
 68	    if values[2] <= 0. || values[3] <= 0. {
 69	        return Err(number(token.name.offset));
 70	    }
 71	    let tile_origin = if object {
 72	        [
 73	            bounds[0] + values[0] * bounds_width,
 74	            bounds[1] + values[1] * bounds_height,
 75	        ]
 76	    } else {
 77	        [values[0], values[1]]
 78	    };
 79	    let tile_width = if object {
 80	        values[2] * bounds_width
 81	    } else {
 82	        values[2]
 83	    };
 84	    let tile_height = if object {
 85	        values[3] * bounds_height
 86	    } else {
 87	        values[3]
 88	    };
 89	    if !tile_origin.iter().all(|n| n.is_finite())
 90	        || !tile_width.is_finite()
 91	        || !tile_height.is_finite()
 92	        || tile_width <= 0.
 93	        || tile_height <= 0.
 94	        || tile_width > 65536.
 95	        || tile_height > 65536.
 96	    {
 97	        return Err(crate::limit(LimitKind::Patterns, token.name.offset));
 98	    }
 99	    let pattern_transform = if let Some(span) = attr(source, tokens, element, b"patternTransform") {
100	        let end = span
101	            .offset
102	            .checked_add(span.length)
103	            .ok_or_else(|| crate::invalid(span.offset))?;
104	        let (matrix, operations) = vexel_svg_values::parse_transform(
105	            source,
106	            vexel_base::Span {
107	                start: span.offset,
108	                end,
109	            },
110	        )
111	        .map_err(|error| unsupported(error.offset))?;
112	        control
113	            .charge(
114	                WorkKind::Transform,
115	                u64::try_from(operations)
116	                    .map_err(|_| crate::limit(LimitKind::Arithmetic, span.offset))?,
117	            )
118	            .map_err(crate::planner_support::stopped)?;
119	        matrix
120	    } else {
121	        affine_identity()
122	    };
123	    let pattern_inverse = crate::clip::inverse_affine(pattern_transform).ok_or_else(|| {
124	        unsupported(
125	            attr(source, tokens, element, b"patternTransform")
126	                .map_or(token.name.offset, |s| s.offset),
127	        )
128	    })?;
129	    let translate = Affine {
130	        e: -tile_origin[0],
131	        f: -tile_origin[1],
132	        ..affine_identity()
133	    };
134	    let user_to_base =
135	        affine_compose(translate, pattern_inverse).ok_or_else(|| number(token.name.offset))?;
136	    Ok(PatternMapping {
137	        definition: ElementId(element),
138	        tile_origin,
139	        tile_width,
140	        tile_height,
141	        user_to_base,
142	        pattern_scale: pattern_transform
143	            .a
144	            .hypot(pattern_transform.b)
145	            .max(pattern_transform.c.hypot(pattern_transform.d)),
146	    })
147	}
