149	fn bbox_number(source: &[u8], span: vexel_xml::XmlSpan) -> Result<f64> {
150	    let bytes = span_bytes(source, span).ok_or_else(|| crate::invalid(span.offset))?;
151	    let percent = bytes.last() == Some(&b'%');
152	    let number_span = if percent {
153	        vexel_xml::XmlSpan {
154	            offset: span.offset,
155	            length: span
156	                .length
157	                .checked_sub(1)
158	                .ok_or_else(|| crate::invalid(span.offset))?,
159	        }
160	    } else {
161	        span
162	    };
163	    let value = parse_number(source, number_span, 0.)?;
164	    Ok(if percent { value / 100. } else { value })
165	}
