 49	        let active = self.active_draft().ok_or_else(|| invalid(0))?;
 50	        if active.scene != token.mark.scene
 51	            || active.nonce != token.nonce
 52	            || active.scene_count != token.scene_count
 53	        {
 54	            return Err(invalid(0));
 55	        }
 56	        let i = self.index(active.scene)?;
