 99	        let i = self.draft_index(&token)?;
100	        let mut released = 0;
101	        for scene in &self.scenes[token.scene_count..] {
102	            released = crate::memory::add(released, scene.storage_bytes()?)?;
103	        }
104	        token.mark.epoch = self.scenes[i].epoch;
105	        self.rollback_internal(token.mark)?;
106	        self.scenes.truncate(token.scene_count);
107	        self.stats.live_bytes -= released;
108	        self.ignored = token.ignored;
109	        self.draft_depth -= 1;
110	        self.drafts[self.draft_depth] = None;
111	        Ok(())
