   161	static bool parse_reference(base_bytes source, svg_xml_span value,
   162	                            svg_xml_span *id)
   163	{
   164	    if (value.offset > source.len || value.length < 7U ||
   165	        value.length > source.len - value.offset ||
   166	        memcmp(source.ptr + value.offset, "url(#", 5U) != 0 ||
   167	        source.ptr[value.offset + value.length - 1U] != ')') return false;
   168	    *id = (svg_xml_span){value.offset + 5U, value.length - 6U};
   169	    return id->length != 0U;
   170	}
   171	
   172	static bool point_inside(const svg_shape_document *doc, size_t shape,
   173	                         double x, double y)
   174	{
   175	    int winding = 0;
   176	    uint8_t parity = 0U;
   177	    size_t first = doc->shape_edge_start[shape];
   178	    size_t end = first + doc->shape_edge_count[shape];
   179	    for (size_t i = first; i < end; ++i) {
   180	        geom_edge edge = doc->edges[i];
   181	        bool up = edge.a.y <= y && edge.b.y > y;
   182	        bool down = edge.b.y <= y && edge.a.y > y;
   183	        if (!up && !down) continue;
   184	        double cross_x = edge.a.x + (y - edge.a.y) *
   185	                         (edge.b.x - edge.a.x) / (edge.b.y - edge.a.y);
   186	        if (cross_x > x) { winding += up ? 1 : -1; parity ^= 1U; }
   187	    }
   188	    return doc->shape_evenodd[shape] ? parity != 0U : winding != 0;
   189	}
   190	
   191	svg_shape_error svg_clip_resolve(base_bytes source, const svg_xml_token *tokens,
   192	                                 size_t token_count,
   193	                                 svg_reference_index *references,
   194	                                 svg_css_sheet *css,
   195	                                 svg_xml_span value,
   196	                                 svg_shape_document *document,
   197	                                 size_t *document_clip_bytes,
   198	                                 geom_affine user_inverse,
   199	                                 const double local_bounds[4],
   200	                                 size_t owner_node,
   201	                                 svg_shape_clip **out,
   202	                                 svg_shape_diagnostic *diagnostic)
   203	{
   204	    if (out == NULL || document == NULL || document_clip_bytes == NULL ||
   205	        css == NULL ||
   206	        local_bounds == NULL) {
   207	        if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_INVALID_ARGUMENT, value.offset};
   208	        return SVG_SHAPE_ERROR_INVALID_ARGUMENT;
   209	    }
   210	    *out = NULL;
   211	    uint8_t *rule_by_offset = NULL;
   212	    svg_xml_span id;
   213	    if (!parse_reference(source, value, &id)) goto unsupported;
   214	    size_t target;
   215	    if (!svg_reference_index_find(source, tokens, token_count, references,
   216	                                  id, &target) ||
   217	        !eq(source, tokens[target].local_name, "clipPath") ||
   218	        tokens[target].prefix.length != 0U) goto unsupported;
   219	    if (attr(source, tokens, token_count, target, "clip-path", &id) ||
   220	        attr(source, tokens, token_count, target, "transform", &id) ||
   221	        attr(source, tokens, token_count, target, "style", &id)) goto unsupported;
   222	    bool object_box = false;
   223	    svg_xml_span units;
   224	    bool has_units = attr(source, tokens, token_count, target, "clipPathUnits", &units);
   225	    if (has_units) {
   226	        if (eq(source, units, "userSpaceOnUse")) object_box = false;
   227	        else if (eq(source, units, "objectBoundingBox")) object_box = true;
   228	        else goto unsupported;
   229	    }
   230	    size_t end_token = element_end(tokens, token_count, target);
   231	    size_t child_start = tokens[target].source.offset + tokens[target].source.length;
   232	    size_t child_end = end_token == target ? child_start : tokens[end_token].source.offset;
   233	    if (child_start > child_end || child_end > source.len) goto unsupported;
   234	    size_t child_length = child_end - child_start;
   235	    if (child_length > CLIP_MAX_REFERENCE_BYTES) goto limit;
   236	    if (child_length == 0U) goto unsupported;
   237	    rule_by_offset = svg_shape_calloc(child_length, sizeof(*rule_by_offset));
   238	    if (rule_by_offset == NULL) {
   239	        if (diagnostic != NULL)
   240	            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, value.offset};
   241	        return SVG_SHAPE_ERROR_OOM;
   242	    }
   243	    svg_shape_error style_error = clip_rule_map(
   244	        css, source, tokens, token_count, target, end_token, child_start,
   245	        child_length, rule_by_offset, diagnostic);
   246	    if (style_error != SVG_SHAPE_ERROR_NONE) {
   247	        svg_shape_free(rule_by_offset);
   248	        return style_error;
   249	    }
   250	    size_t child_count = 0U;
   251	    for (size_t i = target + 1U; i < end_token; ++i) {
   252	        if ((tokens[i].kind == SVG_XML_TOKEN_START_ELEMENT ||
   253	             tokens[i].kind == SVG_XML_TOKEN_EMPTY_ELEMENT) &&
   254	            tokens[i].depth == tokens[target].depth + 1U) {
   255	            if (++child_count > CLIP_MAX_CHILDREN ||
   256	                attr(source, tokens, token_count, i, "clip-path", &units)) goto limit;
   257	        }
   258	    }
   259	    if (child_count == 0U) goto unsupported;
   260	    /* The prefix permits 191 payload bytes; suffix and NUL count in scratch. */
   261	    char prefix_pattern[CLIP_WRAPPER_BUFFER_BYTES];
   262	    int prefix_result = object_box
   263	        ? snprintf(prefix_pattern, sizeof(prefix_pattern),
   264	                   "<svg width=\"1\" height=\"1\" viewBox=\"0 0 1 1\">")
   265	        : snprintf(prefix_pattern, sizeof(prefix_pattern),
   266	                   "<svg width=\"%u\" height=\"%u\" viewBox=\"%.17g %.17g %.17g %.17g\">",
   267	                   document->width, document->height, document->view_x,
   268	                   document->view_y, document->view_width, document->view_height);
   269	    if (prefix_result < 0 || (size_t)prefix_result >= sizeof(prefix_pattern)) goto limit;
   270	    size_t prefix_length = (size_t)prefix_result;
   271	    static const char suffix[] = "</svg>";
   272	    if (prefix_length > SIZE_MAX - sizeof(suffix) - child_length) goto limit;
   273	    size_t total = prefix_length + child_length + sizeof(suffix) - 1U;
   274	    if (total >= CLIP_MAX_JOB_REFERENCE_BYTES) goto limit;
   275	    size_t allocation_bytes = total + 1U;
   276	    if (*document_clip_bytes > CLIP_MAX_JOB_REFERENCE_BYTES - allocation_bytes)
   277	        goto limit;
   278	    uint8_t *scratch = svg_shape_malloc(allocation_bytes);
   279	    svg_shape_clip *clip = svg_shape_calloc(1U, sizeof(*clip));
   280	    if (scratch == NULL || clip == NULL) {
   281	        svg_shape_free(scratch); svg_shape_free(clip);
   282	        svg_shape_free(rule_by_offset);
   283	        if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, value.offset};
   284	        return SVG_SHAPE_ERROR_OOM;
   285	    }
   286	    (void)svg_shape_alloc_set_tag(scratch, SVG_SHAPE_ALLOC_TAG_CLIP_COPY);
   287	    memcpy(scratch, prefix_pattern, prefix_length);
   288	    memcpy(scratch + prefix_length, source.ptr + child_start, child_length);
   289	    memcpy(scratch + prefix_length + child_length, suffix, sizeof(suffix) - 1U);
   290	    scratch[total] = 0U;
   291	    clip->source = scratch;
   292	    clip->source_length = total;
   293	    clip->owner_node = owner_node;
   294	    clip->references = 1U;
   295	    clip->object_bounding_box = object_box;
   296	    clip->user_inverse = user_inverse;
   297	    memcpy(clip->bounds, local_bounds, sizeof(clip->bounds));
   298	    if (object_box && (clip->bounds[2] <= clip->bounds[0] ||
   299	                       clip->bounds[3] <= clip->bounds[1])) {
   300	        svg_clip_destroy(clip); goto unsupported;
   301	    }
   302	    svg_shape_error error = svg_shape_decode((base_bytes){scratch, total}, &clip->geometry, diagnostic);
   303	    if (error != SVG_SHAPE_ERROR_NONE) {
   304	        if (diagnostic != NULL) {
   305	            size_t generated = diagnostic->offset;
   306	            diagnostic->offset = generated >= prefix_length &&
   307	                generated - prefix_length < child_length
   308	                ? child_start + generated - prefix_length : value.offset;
   309	        }
   310	        svg_clip_destroy(clip);
   311	        svg_shape_free(rule_by_offset);
   312	        return error;
   313	    }
   314	    if (clip->geometry.edge_count > CLIP_MAX_EDGES) {
   315	        svg_clip_destroy(clip); goto limit;
   316	    }
   317	    for (size_t shape = 0U; shape < clip->geometry.shape_count; ++shape) {
   318	        size_t offset = clip->geometry.shape_sources[shape].offset;
   319	        if (offset < prefix_length || offset - prefix_length >= child_length) {
   320	            svg_clip_destroy(clip); goto unsupported;
   321	        }
   322	        clip->geometry.shape_evenodd[shape] =
   323	            rule_by_offset[offset - prefix_length] != 0U;
   324	    }
   325	    svg_shape_free(rule_by_offset);
   326	    *document_clip_bytes += allocation_bytes;
   327	    document->has_clips = true;
   328	    *out = clip;
   329	    return SVG_SHAPE_ERROR_NONE;
   330	limit:
   331	    svg_shape_free(rule_by_offset);
   332	    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, value.offset};
   333	    return SVG_SHAPE_ERROR_LIMIT;
   334	unsupported:
   335	    svg_shape_free(rule_by_offset);
   336	    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_UNSUPPORTED, value.offset};
   337	    return SVG_SHAPE_ERROR_UNSUPPORTED;
   338	}
