   340	bool svg_clip_contains(const svg_shape_clip *clip, double x, double y)
   341	{
   342	    if (clip == NULL) return true;
   343	    double root_x = x, root_y = y;
   344	    geom_point local;
   345	    if (!geom_affine_map_point(clip->user_inverse, (geom_point){x, y}, &local))
   346	        return false;
   347	    x = local.x;
   348	    y = local.y;
   349	    if (clip->object_bounding_box) {
   350	        if (clip->bounds[2] <= clip->bounds[0] ||
   351	            clip->bounds[3] <= clip->bounds[1]) return false;
   352	        x = (x - clip->bounds[0]) / (clip->bounds[2] - clip->bounds[0]);
   353	        y = (y - clip->bounds[1]) / (clip->bounds[3] - clip->bounds[1]);
   354	    }
   355	    bool inside = false;
   356	    for (size_t i = 0U; i < clip->geometry.shape_count; ++i) {
   357	        if (clip->geometry.shape_filled[i] && point_inside(&clip->geometry, i, x, y)) {
   358	            inside = true;
   359	            break;
   360	        }
   150	    if let Some(s) = attr(source, tokens, element, b"viewBox") {
   151	        let v = number_list(source, s, 4)?;
   152	        if v.len() != 4 || v[2] <= 0. || v[3] <= 0. {
   153	            return Err(Diagnostic {
   154	                kind: ErrorKind::Viewport,
   155	                offset: s.offset,
   156	            });
   157	        }
   158	        let aspect = if let Some(a) = attr(source, tokens, element, b"preserveAspectRatio") {
   159	            let end = a.offset + a.length;
   160	            vexel_svg_values::parse_preserve_aspect(
   161	                source,
   162	                vexel_base::Span {
   163	                    start: a.offset,
   164	                    end,
   165	                },
   166	            )
   167	            .map_err(|e| Diagnostic {
   168	                kind: ErrorKind::Unsupported,
   169	                offset: e.offset,
   170	            })?
   171	        } else {
   172	            vexel_svg_values::Aspect {
   173	                align_x: 0.5,
   174	                align_y: 0.5,
   175	                none: false,
   176	                slice: false,
   177	                set: true,
   178	            }
   179	        };
   180	        content = vexel_svg_values::viewbox_transform(
   181	            v[0], v[1], v[2], v[3], 0., 0., width, height, aspect,
   182	        )
   183	        .map_err(|_| Diagnostic {
   184	            kind: ErrorKind::Viewport,
   185	            offset: s.offset,
   186	        })?;
   187	        let Some(reference) =
   188	            vexel_geometry::affine_map_point(content, Point { x: ref_x, y: ref_y })
   189	        else {
   190	            return Err(Diagnostic {
   191	                kind: ErrorKind::Viewport,
   192	                offset: s.offset,
   193	            });
   194	        };
   195	        return Ok(MarkerAttributes {
   196	            width,
   197	            height,
   198	            ref_x: reference.x,
   199	            ref_y: reference.y,
   200	            stroke_width_units,
   201	            orient,
   202	            content,
   203	            child_viewport: [v[2], v[3]],
   204	        });
   205	    }
   206	    Ok(MarkerAttributes {
   207	        width,
   208	        height,
   209	        ref_x,
   210	        ref_y,
   211	        stroke_width_units,
   212	        orient,
   213	        content,
   214	        child_viewport,
