457	static bool path_markers(shape_traversal *traversal, size_t shape,
458	                         const svg_css_paint *style, geom_affine transform,
459	                         size_t render_depth)
460	{
461	    const svg_shape_document *document = traversal->builder.doc;
462	    size_t lower = 0U, upper = document->path_segment_count;
463	    while (lower < upper) {
464	        size_t middle = lower + (upper - lower) / 2U;
465	        if (document->path_segments[middle].shape_index < shape)
466	            lower = middle + 1U;
467	        else upper = middle;
468	    }
469	    marker_subpath current = {0};
470	    for (size_t i = lower; i < document->path_segment_count &&
471	         document->path_segments[i].shape_index == shape; ++i) {
472	        /* Copy by value: flushing emits markers whose nested paths append to
473	         * and may reallocate path_segments. */
474	        const svg_shape_path_segment segment_copy = document->path_segments[i];
475	        const svg_shape_path_segment *segment = &segment_copy;
476	        char command = segment->command;
477	        if (command >= 'a' && command <= 'z') command = (char)(command - 'a' + 'A');
478	        if (command == 'M' && !flush_path_subpath(
479	                traversal, shape, style, &current, transform, render_depth))
480	            return false;
481	        if (segment->edge_count == 0U) continue;
482	        if (segment->first_edge > document->edge_count ||
