282	fn parse_orient(source: &[u8], span: XmlSpan) -> Result<MarkerOrient> {
283	    let b = span_bytes(source, span).ok_or_else(|| bad(span.offset))?;
284	    if b.eq_ignore_ascii_case(b"auto") {
285	        return Ok(MarkerOrient::Auto);
286	    }
287	    if b.eq_ignore_ascii_case(b"auto-start-reverse") {
288	        return Ok(MarkerOrient::AutoStartReverse);
289	    }
290	    let mut first = 0usize;
291	    let mut last = b.len();
292	    while first < last && crate::ascii_space(b[first]) {
293	        first += 1;
294	    }
295	    while last > first && crate::ascii_space(b[last - 1]) {
296	        last -= 1;
297	    }
298	    if last - first >= 3 && &b[last - 3..last] == b"deg" {
299	        last -= 3;
300	        while last > first && crate::ascii_space(b[last - 1]) {
301	            last -= 1;
302	        }
303	    }
304	    if first == last {
305	        return Err(number(span.offset));
306	    }
307	    let s = XmlSpan {
308	        offset: span
309	            .offset
310	            .checked_add(first)
311	            .ok_or_else(|| bad(span.offset))?,
312	        length: last - first,
313	    };
314	    Ok(MarkerOrient::Angle(crate::common::parse_number(
315	        source, s, 0.,
316	    )?))
317	}
