217	pub fn direction_angle(edge: Edge) -> f64 {
218	    (edge.b.y - edge.a.y).atan2(edge.b.x - edge.a.x)
219	}
220	pub fn middle_angle(incoming: Edge, outgoing: Edge) -> f64 {
221	    let first = direction_angle(incoming);
222	    let mut delta = (direction_angle(outgoing) - first) % (2.0 * PI);
223	    if delta > PI {
224	        delta -= 2.0 * PI;
225	    } else if delta < -PI {
226	        delta += 2.0 * PI;
227	    }
228	    first + delta * 0.5
229	}
230	pub fn element_scale(m: Affine) -> f64 {
231	    let xx = m.a * m.a + m.b * m.b;
232	    let yy = m.c * m.c + m.d * m.d;
233	    let xy = m.a * m.c + m.b * m.d;
234	    ((xx + yy + ((xx - yy) * (xx - yy) + 4. * xy * xy).sqrt()) * 0.5)
235	        .max(0.)
236	        .sqrt()
237	}
