 95	static bool local_bounds(const svg_shape_document *document, size_t shape,
 96	                         geom_affine transform, double bounds[4])
 97	{
 98	    if (shape >= document->shape_count || document->shape_edge_start == NULL ||
 99	        document->shape_edge_count == NULL || document->edges == NULL)
100	        return false;
101	    geom_affine inverse;
102	    if (!svg_shape_affine_inverse(transform, &inverse)) return false;
103	    size_t first = document->shape_edge_start[shape];
104	    size_t count = document->shape_edge_count[shape];
105	    if (first > document->edge_count || count > document->edge_count - first ||
106	        count == 0U) return false;
107	    double min_x = INFINITY, min_y = INFINITY;
108	    double max_x = -INFINITY, max_y = -INFINITY;
109	    for (size_t i = 0U; i < count; ++i) {
110	        geom_point points[2] = {document->edges[first + i].a,
111	                                document->edges[first + i].b};
112	        for (size_t p = 0U; p < 2U; ++p) {
113	            geom_point local;
114	            if (!geom_affine_map_point(inverse, points[p], &local)) return false;
115	            if (local.x < min_x) min_x = local.x;
116	            if (local.x > max_x) max_x = local.x;
117	            if (local.y < min_y) min_y = local.y;
118	            if (local.y > max_y) max_y = local.y;
119	        }
120	    }
121	    if (!isfinite(min_x) || !isfinite(min_y) || !isfinite(max_x) ||
122	        !isfinite(max_y) || max_x < min_x || max_y < min_y) return false;
123	    bounds[0] = min_x;
124	    bounds[1] = min_y;
125	    bounds[2] = max_x - min_x;
126	    bounds[3] = max_y - min_y;
127	    return true;
128	}
