   118	{
   119	    double xx = transform.a * transform.a + transform.b * transform.b;
   120	    double yy = transform.c * transform.c + transform.d * transform.d;
   121	    double xy = transform.a * transform.c + transform.b * transform.d;
   122	    double maximum = (xx + yy + hypot(xx - yy, 2.0 * xy)) * 0.5;
   123	    return sqrt(fmax(0.0, maximum));
