   180	                SHAPE_MAX_TRAVERSAL_VISITS) {
   181	            fail(traversal->diagnostic, SVG_SHAPE_ERROR_LIMIT,
   182	                 traversal->tokens[marker].name.offset);
   183	            return false;
   184	        }
   185	        traversal->marker_style_token_visits++;
   186	        if ((i & 255U) == 0U && svg_shape_traverse_cancelled(
   187	                traversal, traversal->tokens[i].source.offset)) return false;
   188	        const svg_xml_token *token = &traversal->tokens[i];
   189	        if (token->kind == SVG_XML_TOKEN_START_ELEMENT) {
   190	            while (ancestor_count != 0U &&
   191	                   traversal->tokens[ancestors[ancestor_count - 1U]].depth >=
