 11	/// Parse one CSS/SVG color value within an original source span.
 12	/// The source is borrowed and never copied; malformed spans and values return `None`.
 13	pub fn parse_color(source: &[u8], span: Span) -> Option<[u8; 4]> {
 14	    let raw = span.slice(source)?;
 15	    if raw.is_empty() || raw.len() > MAX_VALUE_BYTES {
 16	        return None;
 17	    }
 18	    let start = raw.iter().position(|b| !ws(*b))?;
 19	    let end = raw.iter().rposition(|b| !ws(*b))? + 1;
 20	    let value = &raw[start..end];
 21	    if eq_ci(value, b"transparent") {
 22	        return Some([0, 0, 0, 0]);
 23	    }
 24	    if value[0] == b'#' {
 25	        return parse_hex(value);
 26	    }
 27	    if value.contains(&b'(') {
 28	        return parse_function(value);
 29	    }
 30	    NAMED_COLORS.iter().find_map(|(name, rgb)| {
 31	        eq_ci(value, name.as_bytes()).then_some([
 32	            (rgb >> 16) as u8,
 33	            (rgb >> 8) as u8,
 34	            *rgb as u8,
 35	            255,
 36	        ])
 37	    })
 38	}
