 40	fn ws(b: u8) -> bool {
 41	    matches!(b, b' ' | b'\t' | b'\r' | b'\n' | 0x0c)
 42	}
 43	fn eq_ci(a: &[u8], b: &[u8]) -> bool {
 44	    a.len() == b.len() && a.iter().zip(b).all(|(x, y)| x.to_ascii_lowercase() == *y)
 45	}
 46	fn hex(b: u8) -> Option<u8> {
 47	    match b {
 48	        b'0'..=b'9' => Some(b - b'0'),
 49	        b'a'..=b'f' => Some(b - b'a' + 10),
 50	        b'A'..=b'F' => Some(b - b'A' + 10),
 51	        _ => None,
 52	    }
 53	}
 54	fn parse_hex(v: &[u8]) -> Option<[u8; 4]> {
 55	    if !matches!(v.len(), 4 | 5 | 7 | 9) {
 56	        return None;
 57	    }
 58	    let short = v.len() <= 5;
 59	    let count = if matches!(v.len(), 5 | 9) { 4 } else { 3 };
 60	    let mut out = [0; 4];
 61	    for (i, c) in out.iter_mut().take(count).enumerate() {
 62	        let at = 1 + i * (if short { 1 } else { 2 });
 63	        let hi = hex(*v.get(at)?)?;
 64	        *c = if short {
 65	            hi * 17
 66	        } else {
 67	            hi * 16 + hex(*v.get(at + 1)?)?
 68	        };
 69	    }
 70	    if count == 3 {
 71	        out[3] = 255;
 72	    }
 73	    Some(out)
 74	}
