304	fn clamp(v: f64, l: f64, h: f64) -> f64 {
305	    v.max(l).min(h)
306	}
307	fn byte(v: f64) -> u8 {
308	    (clamp(v, 0.0, 255.0) + 0.5).floor() as u8
309	}
310	fn hsl_rgb(mut h: f64, s: f64, l: f64, o: &mut [u8; 4]) {
311	    h = h.rem_euclid(360.0);
312	    let s = clamp(s, 0.0, 1.0);
313	    let l = clamp(l, 0.0, 1.0);
314	    let c = (1.0 - (2.0 * l - 1.0).abs()) * s;
315	    let x = c * (1.0 - ((h / 60.0) % 2.0 - 1.0).abs());
316	    let (r, g, b) = if h < 60.0 {
317	        (c, x, 0.0)
318	    } else if h < 120.0 {
319	        (x, c, 0.0)
320	    } else if h < 180.0 {
321	        (0.0, c, x)
322	    } else if h < 240.0 {
323	        (0.0, x, c)
324	    } else if h < 300.0 {
325	        (x, 0.0, c)
326	    } else {
327	        (c, 0.0, x)
328	    };
329	    let m = l - c * 0.5;
330	    o[0] = byte((r + m) * 255.0);
331	    o[1] = byte((g + m) * 255.0);
332	    o[2] = byte((b + m) * 255.0)
333	}
