   425	pub fn inverse_affine(m: Affine) -> Option<Affine> {
   426	    if !affine_valid(m) {
   427	        return None;
   428	    }
   429	    let det = m.a * m.d - m.b * m.c;
   430	    if !det.is_finite() || det == 0.0 {
   431	        return None;
   432	    }
   433	    let v = Affine {
   434	        a: m.d / det,
   435	        b: -m.b / det,
   436	        c: -m.c / det,
   437	        d: m.a / det,
   438	        e: (m.c * m.f - m.d * m.e) / det,
   439	        f: (m.b * m.e - m.a * m.f) / det,
   440	    };
   441	    affine_valid(v).then_some(v)
   442	}
