   444	/// Maps one clip-local point into document coordinates, including the target's
   445	/// object-bounding-box normalization when present.
   446	pub fn local_to_document(view: SceneView<'_>, clip: ClipId, point: Point) -> Option<Point> {
   447	    let c = view.clip(clip)?;
   448	    let mut point = point;
   449	    if c.object_bounding_box {
   450	        let [x0, y0, x1, y1] = c.bounds;
   451	        if x1 <= x0 || y1 <= y0 {
   452	            return None;
   453	        }
   454	        point.x = x0 + point.x * (x1 - x0);
   455	        point.y = y0 + point.y * (y1 - y0);
   456	    }
   457	    affine_map_point(inverse_affine(c.user_inverse)?, point)
   458	}
